Object.assign(window.EL_CAPSULES, {
  "eso2:Oct:1": {"title": "El imperio donde no se ponía el sol", "steps": [{"type": "hook", "kicker": "Historia · Imperios", "h": "¿Puede un imperio abarcar todo el planeta conocido?", "scenario": "Eres cartógrafo real en 1580, en la corte de Felipe II. Te piden dibujar un mapa con todos los territorios de la Corona.", "body": "En el siglo XVI, la <b>Monarquía Hispánica</b> alcanzó una extensión sin precedentes: Europa, América, África y Asia. Nunca antes un solo reino había necesitado un mapa tan grande."}, {"type": "theory", "kicker": "Historia · Política imperial", "h": "Carlos I y Felipe II: dos reyes, un imperio", "body": "<b>Carlos I</b> (1516-1556) heredó territorios de sus cuatro abuelos: España, Países Bajos, el Imperio austríaco y posesiones italianas; además fue elegido <b>emperador del Sacro Imperio Romano Germánico</b> (Carlos V). Su hijo <b>Felipe II</b> (1556-1598) heredó España, América, Nápoles y Países Bajos, y en 1580 incorporó <b>Portugal y su imperio</b> tras la crisis sucesoria portuguesa. Con esta unión, la Monarquía Hispánica llegó a dominar territorios en los cuatro continentes conocidos, dando origen a la célebre expresión: <b>«el imperio en el que nunca se pone el sol»</b>.", "diagram": "EUROPA: España, Nápoles, Milán, Países Bajos<br>AMÉRICA: Virreinato de Nueva España, Virreinato del Perú<br>ÁFRICA: plazas en el norte de África (Orán, Melilla)<br>ASIA: Filipinas (unión con Portugal: Goa, Macao)"}, {"type": "quiz", "kicker": "Historia · Comprueba", "h": "¿Qué territorio se incorporó a la Corona en 1580?", "q": "¿Qué hecho histórico llevó a Felipe II a controlar también los territorios portugueses en 1580?", "opts": [{"t": "La conquista militar directa de Lisboa sin motivo dinástico", "ok": false}, {"t": "La crisis sucesoria portuguesa, que le permitió reclamar la corona por herencia", "ok": true}, {"t": "Un tratado de compraventa con el rey de Portugal", "ok": false}, {"t": "La derrota de Portugal en la batalla de Lepanto", "ok": false}], "okMsg": "Correcto. Felipe II reclamó la corona portuguesa por derechos dinásticos tras la crisis sucesoria de 1580, uniendo ambos imperios coloniales.", "noMsg": "No exactamente. Felipe II no conquistó Portugal por la fuerza como primera vía: aprovechó una crisis sucesoria y sus derechos hereditarios para reclamar el trono."}, {"type": "reflect", "kicker": "Historia · Tu turno", "h": "Dibuja el imperio", "body": "Vas a construir tu propio mapa mental del imperio español en 1580, continente por continente.", "prompt": "Elabora una lista o esquema con los territorios que controlaba la Monarquía Hispánica en 1580 en <b>Europa, América, África y Asia</b>. Para cada continente, añade al menos un territorio y una frase explicando su importancia (económica, estratégica o religiosa)."}]},
  "eso2:Oct:2": {"title": "Trento: la Iglesia responde", "steps": [{"type": "hook", "kicker": "Historia · Reforma y Contrarreforma", "h": "¿Cómo responde una institución cuando la critican por dentro?", "scenario": "Corre el año 1545. Martín Lutero lleva casi 30 años cuestionando a la Iglesia católica. Roma convoca a sus obispos y teólogos en una ciudad del norte de Italia: Trento.", "body": "La <b>Reforma protestante</b>, iniciada por Lutero en 1517, había fracturado la cristiandad occidental. La Iglesia católica necesitaba decidir: ¿ceder, ignorar o responder con firmeza?"}, {"type": "theory", "kicker": "Historia · Concilio de Trento", "h": "Un concilio para definir la fe católica", "body": "El <b>Concilio de Trento</b> (1545-1563) se reunió en varias sesiones a lo largo de casi veinte años. Su objetivo era doble: <b>reafirmar la doctrina católica</b> frente a las tesis protestantes y <b>reformar</b> los abusos internos de la Iglesia (venta de indulgencias, falta de formación del clero, absentismo de obispos). De este concilio nace lo que se conoce como la <b>Contrarreforma</b>: la respuesta organizada de la Iglesia católica ante la fractura religiosa de Europa.", "diagram": "DOCTRINA: se reafirma la salvación por fe y obras, y la autoridad de la tradición junto a la Biblia<br>DISCIPLINA: obligación de residencia de los obispos, creación de seminarios para formar sacerdotes<br>PRÁCTICA: se corrigen abusos en la venta de indulgencias<br>ARTE Y CULTURA: impulso del arte religioso como herramienta didáctica"}, {"type": "quiz", "kicker": "Historia · Comprueba", "h": "¿Cuál era el objetivo principal de Trento?", "q": "¿Cuál de estas fue una decisión real del Concilio de Trento?", "opts": [{"t": "Aceptar la doctrina luterana de la salvación solo por fe", "ok": false}, {"t": "Obligar a los obispos a residir en sus diócesis y crear seminarios para formar sacerdotes", "ok": true}, {"t": "Suprimir el culto a los sacramentos", "ok": false}, {"t": "Trasladar la sede papal a Trento de forma permanente", "ok": false}], "okMsg": "Exacto. Una de las grandes reformas disciplinarias de Trento fue exigir residencia episcopal y crear seminarios, mejorando la formación del clero.", "noMsg": "Revisa el texto: Trento no aceptó las tesis luteranas, sino que reafirmó la doctrina católica y reformó la disciplina interna, como la residencia de obispos y los seminarios."}, {"type": "reflect", "kicker": "Historia · Tu turno", "h": "Tres decisiones que cambiaron la Iglesia", "body": "Vas a leer un texto adaptado sobre el Concilio de Trento y extraer sus decisiones más relevantes.", "prompt": "A partir de lo trabajado sobre el Concilio de Trento, identifica y redacta con tus palabras <b>3 decisiones importantes</b> que tomó el concilio, explicando en 2-3 líneas cada una por qué fueron relevantes para la Iglesia católica del siglo XVI."}]},
  "eso2:Oct:3": {"title": "Contrarreforma a debate", "steps": [{"type": "hook", "kicker": "Historia · Pensamiento crítico", "h": "¿Defender una fe siempre significa restringir la libertad de los demás?", "scenario": "En una España del siglo XVI cada vez más vigilada por la Inquisición, un librero se pregunta si debe ocultar ciertos libros antes de que lleguen los censores.", "body": "La <b>Contrarreforma española</b> combinó fervor religioso, control social y un enorme impulso cultural y artístico. Hoy toca mirarla sin prejuicios y con argumentos."}, {"type": "theory", "kicker": "Historia · Contrarreforma española", "h": "Fe, control y cultura a la vez", "body": "España se convirtió en el gran bastión de la <b>Contrarreforma</b>: la <b>Inquisición</b> vigilaba la ortodoxia religiosa, se reforzó la <b>censura de libros</b> (Índice de libros prohibidos) y se impulsó una intensa vida religiosa y misionera. Al mismo tiempo, este periodo coincidió con el <b>Siglo de Oro</b> español: un extraordinario florecimiento del arte, la literatura y la arquitectura religiosa, muchas veces al servicio de la fe católica. Historiadores debaten si la Contrarreforma fue sobre todo una <b>defensa legítima de la identidad religiosa</b> frente a la fragmentación de la cristiandad, o si supuso una <b>restricción severa</b> de la libertad de pensamiento y de conciencia. Ambas lecturas tienen argumentos serios y no son mutuamente excluyentes.", "diagram": "A FAVOR (defensa de la fe): cohesión religiosa, identidad cultural, mecenazgo artístico<br>EN CONTRA (restricción): censura de libros, control inquisitorial, limitación del pensamiento<br>MATIZ: ambas fuerzas convivieron en la misma época"}, {"type": "quiz", "kicker": "Historia · Comprueba", "h": "¿Qué caracterizó a la Contrarreforma española?", "q": "¿Cuál de estas afirmaciones describe mejor la Contrarreforma española?", "opts": [{"t": "Fue solo un movimiento de censura, sin ningún impacto cultural", "ok": false}, {"t": "Combinó defensa religiosa, control inquisitorial y un notable florecimiento cultural y artístico", "ok": true}, {"t": "Supuso la desaparición total de la Inquisición en España", "ok": false}, {"t": "Fue idéntica en objetivos a la Reforma protestante", "ok": false}], "okMsg": "Correcto. La Contrarreforma española combinó control religioso (Inquisición, censura) con un gran impulso artístico y cultural, el Siglo de Oro.", "noMsg": "Piensa de nuevo: la Contrarreforma no fue solo censura ni fue igual a la Reforma protestante; combinó control religioso con florecimiento cultural."}, {"type": "reflect", "kicker": "Historia · Tu turno", "h": "A debate: ¿fe o restricción?", "body": "Vas a preparar un debate en clase sobre la Contrarreforma, defendiendo argumentos con rigor histórico, sin caer en juicios simples.", "prompt": "Prepara por escrito <b>dos argumentos</b> a favor de la idea de que la Contrarreforma fue una <b>defensa legítima de la fe</b>, y <b>dos argumentos</b> a favor de la idea de que supuso una <b>restricción de la libertad</b>. Termina con tu propia conclusión razonada en 3-4 líneas."}]},
  "eso2:Oct:4": {"title": "Obedecer a Dios antes que a los hombres", "steps": [{"type": "hook", "kicker": "Fe y valores · Hechos 5", "h": "¿Qué haces cuando una orden humana choca con tu conciencia?", "scenario": "Los apóstoles han sido arrestados por predicar en Jerusalén. El Sanedrín les ordena callar. Pedro y los demás deben decidir en ese mismo instante.", "body": "En el siglo XVI, católicos y protestantes vivieron dilemas parecidos: ¿a quién obedecer cuando la autoridad religiosa y la conciencia personal no coinciden?"}, {"type": "theory", "kicker": "Fe y valores · Hechos 5:29", "h": "Una convicción que atraviesa la historia", "body": "En <b>Hechos 5:29</b>, Pedro y los apóstoles responden ante el Sanedrín: <b>«Es necesario obedecer a Dios antes que a los hombres»</b>. No es una llamada a la rebeldía sin más, sino la afirmación de que existe una autoridad última por encima de cualquier poder humano. Curiosamente, durante el siglo XVI, <b>ambos bandos</b> del conflicto religioso —reformadores protestantes y defensores católicos de Trento— apelaron a esta misma convicción: creían obedecer a Dios por encima de las presiones políticas o sociales de su tiempo. Esto nos recuerda que la fe sincera puede llevar a conclusiones distintas, y que la historia religiosa no siempre se reduce a buenos contra malos.", "diagram": "SANEDRÍN ordena → CALLAR<br>APÓSTOLES responden → «Obedecer a Dios antes que a los hombres»<br>SIGLO XVI: reformadores y defensores de Trento invocan la misma convicción de fondo"}, {"type": "quiz", "kicker": "Fe y valores · Comprueba", "h": "¿Qué significa el versículo de Hechos 5:29?", "q": "¿Qué idea central transmite Hechos 5:29 en el contexto del relato?", "opts": [{"t": "Que nunca hay que respetar ninguna autoridad humana", "ok": false}, {"t": "Que existe una autoridad última (Dios) que puede estar por encima de una orden humana injusta", "ok": true}, {"t": "Que los apóstoles decidieron abandonar su misión para evitar problemas", "ok": false}, {"t": "Que el Sanedrín tenía razón y los apóstoles debían obedecerle", "ok": false}], "okMsg": "Correcto. El versículo afirma que hay una autoridad última —Dios— que puede estar por encima de un mandato humano injusto, sin negar el valor del orden social.", "noMsg": "Vuelve al texto: los apóstoles no rechazan toda autoridad, afirman que, ante un conflicto claro, la obediencia a Dios tiene prioridad."}, {"type": "reflect", "kicker": "Fe y valores · Tu turno", "h": "Ensayo: fe y poder en el imperio", "body": "Cierra el mes uniendo historia y reflexión personal en un ensayo bien argumentado.", "prompt": "Escribe un ensayo titulado <b>«El Imperio Español: fe y poder»</b> (300-400 palabras) en el que expliques cómo se entrelazaron la política imperial de Carlos I y Felipe II, la respuesta católica de Trento y la Contrarreforma, y termines relacionando estos hechos con el principio de Hechos 5:29 sobre obedecer a Dios antes que a los hombres."}]},
  "eso2:Nov:1": {"title": "Entrando en La Mancha", "steps": [{"type": "hook", "kicker": "Lengua · Cervantes", "h": "¿Puede la lectura excesiva volvernos locos... o lúcidos?", "scenario": "Un hidalgo de mediana edad, aficionado a libros de caballerías, decide un día salir a los caminos de La Mancha convertido en caballero andante.", "body": "Así arranca una de las obras más importantes de la literatura universal: <b>Don Quijote de la Mancha</b>, de Miguel de Cervantes."}, {"type": "theory", "kicker": "Lengua · Cervantes y su obra", "h": "Cervantes, su época y el inicio de la novela", "body": "<b>Miguel de Cervantes</b> escribió el <b>Quijote</b> en dos partes (1605 y 1615), en plena España del Siglo de Oro. La obra narra las aventuras de <b>Alonso Quijano</b>, un hidalgo que, tras leer demasiados libros de caballerías, pierde el juicio y decide convertirse en el caballero andante <b>Don Quijote</b>, acompañado de su escudero <b>Sancho Panza</b>. En el <b>capítulo 1</b> se presenta al protagonista y su locura; en el <b>capítulo 8</b> ocurre el célebre episodio de los <b>molinos de viento</b>, que Don Quijote confunde con gigantes; en el <b>capítulo 22</b>, libera a un grupo de <b>galeotes</b> (presos condenados a remar en galeras) en nombre de la justicia y la libertad, con consecuencias inesperadas.", "diagram": "CAP. 1: locura e investidura como caballero<br>CAP. 8: los molinos de viento (gigantes imaginados)<br>CAP. 22: liberación de los galeotes (justicia idealista)"}, {"type": "quiz", "kicker": "Lengua · Comprueba", "h": "¿Qué ocurre en el capítulo 8?", "q": "En el capítulo 8, ¿qué confunde Don Quijote con gigantes?", "opts": [{"t": "Un rebaño de ovejas", "ok": false}, {"t": "Unos molinos de viento", "ok": true}, {"t": "Unas estatuas de piedra", "ok": false}, {"t": "Un grupo de soldados", "ok": false}], "okMsg": "Correcto. Don Quijote ataca los molinos de viento creyendo que son gigantes, en uno de los episodios más famosos de la literatura española.", "noMsg": "No es correcto: el episodio más famoso del capítulo 8 son los molinos de viento, que Don Quijote confunde con gigantes."}, {"type": "reflect", "kicker": "Lengua · Tu turno", "h": "Resume y analiza", "body": "Vas a demostrar que comprendes en profundidad los tres episodios clave de esta semana.", "prompt": "Lee (o repasa) los capítulos 1, 8 y 22 del Quijote (edición ESO). Para cada capítulo, escribe un breve <b>resumen</b> (3-4 líneas) y un <b>breve análisis</b> señalando qué revela ese episodio sobre la personalidad de Don Quijote."}]},
  "eso2:Nov:2": {"title": "Cervantes, crítico de su tiempo", "steps": [{"type": "hook", "kicker": "Lengua · Crítica social", "h": "¿Puede una novela de aventuras ser también una crítica social encubierta?", "scenario": "Bajo la aparente comicidad de un hidalgo que lucha contra molinos, Cervantes esconde observaciones muy afiladas sobre la sociedad de su época.", "body": "El Quijote no es solo una parodia de libros de caballerías: es también un <b>espejo crítico</b> de la España del siglo XVII."}, {"type": "theory", "kicker": "Lengua · La crítica social en el Quijote", "h": "Lo que Cervantes señala sin decirlo directamente", "body": "A través del humor y la aventura, Cervantes critica varios aspectos de su sociedad: la <b>nobleza ociosa</b> que vive de las apariencias sin ocupación real; el sistema de <b>justicia</b>, cuestionado en el episodio de los galeotes, donde no siempre se castiga con equidad; y los <b>libros de caballerías</b> mismos, cuyo consumo desmedido —como el de Alonso Quijano— podía alejar a las personas de la realidad. También aparece una crítica sutil a la <b>obsesión social por el honor y la apariencia</b>, muy presente en la España de la época.", "diagram": "CRÍTICA 1: la nobleza ociosa y la obsesión por las apariencias<br>CRÍTICA 2: la justicia y el trato a los galeotes/presos<br>CRÍTICA 3: el exceso de libros de caballerías y la evasión de la realidad"}, {"type": "quiz", "kicker": "Lengua · Comprueba", "h": "¿Qué crítica social aparece en el episodio de los galeotes?", "q": "¿Qué critica principalmente Cervantes en el episodio de los galeotes (cap. 22)?", "opts": [{"t": "La falta de caballos en los caminos de España", "ok": false}, {"t": "El sistema de justicia y la forma de castigar a los presos", "ok": true}, {"t": "La escasa producción agrícola de La Mancha", "ok": false}, {"t": "El precio de los libros de caballerías", "ok": false}], "okMsg": "Correcto. El episodio de los galeotes permite a Cervantes cuestionar el sistema de justicia y el trato dado a los condenados.", "noMsg": "Repasa el episodio: los galeotes son presos camino de las galeras, y ese pasaje sirve a Cervantes para cuestionar el sistema de justicia de su época."}, {"type": "reflect", "kicker": "Lengua · Tu turno", "h": "Tres críticas, con pruebas del texto", "body": "Vas a argumentar, apoyándote en los episodios leídos, qué aspectos de la sociedad de su tiempo cuestiona Cervantes.", "prompt": "Identifica y redacta <b>3 críticas</b> que Cervantes hace a la sociedad de su tiempo a través del Quijote. Para cada una, cita o menciona un episodio concreto (capítulo 1, 8 o 22) que la ejemplifique."}]},
  "eso2:Nov:3": {"title": "Ironía y parodia: el estilo de Cervantes", "steps": [{"type": "hook", "kicker": "Lengua · Estilo literario", "h": "¿Cómo se puede reír un autor de su propio personaje... y aun así hacerlo entrañable?", "scenario": "Un narrador que duda de sus propias fuentes, un hidalgo que ve gigantes donde hay molinos: el estilo de Cervantes está lleno de guiños al lector.", "body": "Esta semana entramos en el <b>taller literario</b> de Cervantes: cómo construye la ironía y la parodia."}, {"type": "theory", "kicker": "Lengua · Ironía y parodia", "h": "Las herramientas de Cervantes", "body": "La <b>ironía</b> consiste en decir o sugerir algo distinto —a menudo lo contrario— de lo que literalmente se afirma, generando un efecto crítico o humorístico. Cervantes la usa constantemente, por ejemplo al presentar como heroicas acciones que resultan absurdas (los molinos de viento) o al inventar un supuesto autor árabe, <b>Cide Hamete Benengeli</b>, cuya fiabilidad pone en duda el propio narrador. La <b>parodia</b> consiste en imitar deliberadamente un género o estilo para ridiculizarlo o comentarlo: todo el Quijote es, en el fondo, una <b>parodia de los libros de caballerías</b>, con un caballero envejecido, un caballo escuálido (Rocinante) y aventuras que fracasan en vez de triunfar gloriosamente.", "diagram": "IRONÍA: gigantes que en realidad son molinos<br>IRONÍA: narrador que duda de su propia fuente (Cide Hamete)<br>PARODIA: caballero viejo y pobre en vez de joven y noble<br>PARODIA: Rocinante, caballo débil, en vez de corcel heroico"}, {"type": "quiz", "kicker": "Lengua · Comprueba", "h": "¿Qué es la parodia en el Quijote?", "q": "¿Cuál de estos elementos es un ejemplo claro de parodia de los libros de caballerías?", "opts": [{"t": "Que Don Quijote sepa leer y escribir", "ok": false}, {"t": "Que Don Quijote sea un hidalgo mayor y pobre, montado en Rocinante, un caballo débil, en vez de un joven caballero con un corcel poderoso", "ok": true}, {"t": "Que la novela se publicara en dos partes", "ok": false}, {"t": "Que Sancho Panza tenga un nombre gracioso", "ok": false}], "okMsg": "Correcto. La imagen de un hidalgo envejecido y pobre sobre un caballo débil parodia directamente al caballero joven y glorioso de los libros de caballerías.", "noMsg": "Piensa en la parodia: se trata de invertir los rasgos típicos del caballero de los libros de caballerías, como hace Cervantes con la edad y el caballo de Don Quijote."}, {"type": "reflect", "kicker": "Lengua · Tu turno", "h": "Caza de ironías y parodias", "body": "Vas a rastrear en los episodios leídos ejemplos concretos del estilo característico de Cervantes.", "prompt": "Identifica en el texto <b>3 ejemplos de ironía</b> y <b>2 ejemplos de parodia</b>. Para cada ejemplo, explica en una frase por qué lo consideras irónico o paródico."}]},
  "eso2:Nov:4": {"title": "La sabiduría que viene de Dios", "steps": [{"type": "hook", "kicker": "Fe y valores · Proverbios 2", "h": "¿Puede un 'loco' poseer una sabiduría más profunda que quienes lo rodean?", "scenario": "Don Quijote desvaría sobre caballeros y gigantes, pero también pronuncia discursos llenos de idealismo, justicia y coherencia moral. Sancho, por su parte, aporta el sentido común del pueblo.", "body": "La Biblia nos ofrece una clave distinta para pensar la sabiduría, más allá de la locura o la cordura aparentes."}, {"type": "theory", "kicker": "Fe y valores · Proverbios 2:6", "h": "Sabiduría literaria y sabiduría bíblica", "body": "<b>Proverbios 2:6</b> afirma: <b>«Porque el Señor da la sabiduría, y de su boca viene el conocimiento»</b>. En el Quijote conviven al menos dos tipos de sabiduría: la de <b>Sancho Panza</b>, hecha de refranes, sentido práctico y experiencia popular; y la de <b>Don Quijote</b>, un idealismo elevado sobre la justicia, el honor y la libertad, aunque distorsionado por su locura. Ninguna de las dos es sabiduría plena por sí sola: la perspectiva bíblica añade que la <b>verdadera sabiduría</b> no nace solo del ingenio humano —literario o popular— sino que es un <b>don que procede de Dios</b>, capaz de dar sentido tanto a los ideales como a la experiencia cotidiana.", "diagram": "SABIDURÍA DE SANCHO: refranes, sentido práctico, experiencia<br>SABIDURÍA DE DON QUIJOTE: idealismo, justicia, honor (mezclado con locura)<br>PROVERBIOS 2:6: la sabiduría verdadera procede de Dios"}, {"type": "quiz", "kicker": "Fe y valores · Comprueba", "h": "¿Qué afirma Proverbios 2:6?", "q": "Según Proverbios 2:6, ¿cuál es el origen último de la verdadera sabiduría?", "opts": [{"t": "La acumulación de libros y lecturas", "ok": false}, {"t": "El Señor: la sabiduría y el conocimiento vienen de Dios", "ok": true}, {"t": "La experiencia exclusivamente práctica, sin ninguna otra fuente", "ok": false}, {"t": "El estatus social y la nobleza de nacimiento", "ok": false}], "okMsg": "Correcto. Proverbios 2:6 sitúa a Dios como origen último de la sabiduría y el conocimiento, por encima de cualquier otra fuente humana.", "noMsg": "Revisa el versículo: Proverbios 2:6 afirma explícitamente que es el Señor quien da la sabiduría y de quien procede el conocimiento."}, {"type": "reflect", "kicker": "Fe y valores · Tu turno", "h": "Comentario literario final", "body": "Cierra el mes conectando tu análisis literario del Quijote con la reflexión bíblica sobre la sabiduría.", "prompt": "Escribe un comentario literario titulado <b>«El Quijote»</b> (400-500 palabras) que responda a la pregunta: <b>¿qué tipo de sabiduría posee Don Quijote?</b> Relaciona el idealismo y la locura del personaje con la sabiduría práctica de Sancho y con la idea bíblica de Proverbios 2:6 de que la verdadera sabiduría procede de Dios."}]},
  "eso2:Dic:1": {"title": "El Niño perdido: Lope de Vega busca a Dios", "steps": [{"type": "hook", "kicker": "Siglo de Oro", "h": "¿Puede un poema ser también una búsqueda?", "scenario": "Imagina un poema donde el propio poeta se convierte en pastor y sale a buscar, entre la nieve y la noche, a un Niño que se ha perdido. No es un cuento cualquiera: es Lope de Vega hablando de su propia alma.", "body": "En el <b>Siglo de Oro</b> español, los grandes poetas no solo escribían sobre el amor o la guerra: también convertían la Navidad en materia literaria de primer nivel. Lope de Vega, el escritor más prolífico de la lengua española, escribió villancicos y poemas navideños donde el misterio del nacimiento de Jesús se mezcla con la vida cotidiana del pastor castellano. Esta semana vamos a leer un fragmento de «El niño perdido» y a desmontarlo como lo haría un filólogo: género, tema y lenguaje."}, {"type": "theory", "kicker": "Análisis literario", "h": "Cómo se analiza un poema del Siglo de Oro", "body": "Para analizar «El niño perdido» de Lope de Vega necesitamos tres herramientas básicas. El <b>género</b>: se trata de un poema religioso de tradición pastoril, cercano al villancico navideño, que dramatiza la búsqueda del Niño Jesús como si fuera un pastor perdido en el campo. El <b>tema</b>: bajo la anécdota pastoril se esconde una alegoría espiritual, la del alma cristiana que busca a Dios y no lo encuentra a la primera, un motivo muy típico de la mística y la poesía religiosa barroca. El <b>lenguaje</b>: Lope combina un <i>registro popular</i> (vocabulario pastoril, tono de canción) con una intención <i>culta y teológica</i>, logrando que un poema aparentemente sencillo contenga una reflexión profunda sobre la Encarnación.", "diagram": "GÉNERO → poesía pastoril-religiosa <br> TEMA → la búsqueda del alma que busca a Dios <br> LENGUAJE → sencillez popular + hondura teológica <br> RECURSO CLAVE → la alegoría (el pastor = el creyente; el Niño perdido = Dios que se hace cercano y vulnerable)"}, {"type": "quiz", "kicker": "Comprueba", "h": "¿Qué recurso literario usa Lope de Vega?", "q": "En «El niño perdido», ¿qué recurso literario permite que la búsqueda pastoril represente también una búsqueda espiritual?", "opts": [{"t": "La alegoría, donde el pastor representa al creyente y el Niño perdido representa a Dios", "ok": true}, {"t": "La metáfora pura, sin ninguna relación con la religión", "ok": false}, {"t": "La rima consonante, que es lo único importante del poema", "ok": false}, {"t": "La ironía, porque Lope se burla de la fe popular", "ok": false}], "okMsg": "Exacto. La alegoría es la clave: bajo la historia del pastor que busca a su Niño perdido, Lope construye una imagen del alma que busca a Dios. Por eso el poema puede leerse a la vez como escena costumbrista y como teología en verso.", "noMsg": "Repasa el diagrama: el poema funciona en dos niveles a la vez. La superficie (un pastor busca a un niño perdido) esconde un significado espiritual (el alma busca a Dios). Ese doble nivel con correspondencia punto por punto se llama alegoría."}, {"type": "reflect", "kicker": "Tu turno", "h": "Diario de lector: género, tema y lenguaje", "body": "Vas a redactar tu primera entrada del portfolio «La Navidad en el Siglo de Oro», centrada en el fragmento de «El niño perdido» que has leído en clase.", "prompt": "Escribe un análisis breve (mínimo 10 líneas) en el que identifiques: 1) el género del poema y por qué lo consideras así; 2) el tema principal, explicando la alegoría entre el pastor y el creyente; 3) dos ejemplos concretos de lenguaje (palabras o versos) que muestren la mezcla entre lo popular y lo teológico. Termina con una frase personal: ¿alguna vez has sentido que 'buscabas' algo espiritual sin encontrarlo enseguida?"}]},
  "eso2:Dic:2": {"title": "El pincel y el misterio: pintar la Navidad", "steps": [{"type": "hook", "kicker": "Arte sacro", "h": "¿Cómo se pinta un misterio que no se puede ver?", "scenario": "Un pintor del Siglo de Oro se enfrenta a un problema imposible: representar en un lienzo el momento en que Dios se hace niño. No puede pintar la fe directamente, así que recurre a la luz, la composición y el gesto para que el espectador la sienta.", "body": "Velázquez y El Greco pertenecen a generaciones distintas del Siglo de Oro, pero ambos se enfrentaron al mismo reto: pintar la <b>Encarnación</b>, es decir, el momento en que 'lo divino' se vuelve 'humano' y visible. El Greco, con su estilo alargado y espiritual, y Velázquez, con su naturalismo y manejo extraordinario de la luz, resolvieron ese reto de maneras muy distintas. Esta semana vas a mirar un cuadro del Nacimiento como si fueras crítico de arte: no solo 'qué se ve', sino 'qué significa lo que se ve'."}, {"type": "theory", "kicker": "Herramientas de análisis", "h": "Cómo se analiza una pintura religiosa", "body": "Analizar un cuadro no es solo describirlo: es explicar cómo la <b>composición pictórica</b> transmite un mensaje. Debes fijarte en la <b>disposición de las figuras</b> (¿quién está en el centro?, ¿quién mira a quién?), el <b>uso de la luz</b> (en el Barroco, la luz suele señalar lo divino, un recurso llamado <i>tenebrismo</i> cuando el contraste con la oscuridad es muy fuerte), el <b>color</b> y los <b>gestos y miradas</b> de los personajes, que dirigen la atención del espectador hacia el Niño. En los Nacimientos del Siglo de Oro, la pobreza del pesebre se combina casi siempre con una luz que dignifica la escena: la grandeza no está en el lujo, sino en lo que ha llegado.", "diagram": "COMPOSICIÓN → qué figura ocupa el centro y por qué <br> LUZ → el tenebrismo señala lo sagrado en medio de la pobreza <br> GESTOS/MIRADAS → dirigen la atención del espectador <br> MENSAJE → la grandeza de Dios se manifiesta en la humildad del pesebre"}, {"type": "quiz", "kicker": "Comprueba", "h": "¿Qué recurso pictórico destaca lo sagrado?", "q": "En los cuadros del Nacimiento del Siglo de Oro, ¿qué recurso se usa habitualmente para señalar la presencia de lo divino en medio de una escena humilde?", "opts": [{"t": "El contraste de luz y sombra (tenebrismo), que ilumina al Niño en medio de la oscuridad", "ok": true}, {"t": "El uso exclusivo de colores dorados en todo el cuadro", "ok": false}, {"t": "La ausencia total de figuras humanas alrededor del Niño", "ok": false}, {"t": "Un marco decorado con piedras preciosas reales", "ok": false}], "okMsg": "Correcto. El tenebrismo, ese fuerte contraste entre luz y sombra, es uno de los recursos más característicos del Barroco español para señalar que en medio de la pobreza del pesebre está sucediendo algo sagrado.", "noMsg": "Piensa en el diagrama: el recurso no tiene que ver con el lujo ni con quitar figuras del cuadro, sino con cómo se usa la luz. El contraste fuerte entre zonas iluminadas y zonas oscuras (tenebrismo) es la clave para señalar lo divino en medio de lo humilde."}, {"type": "reflect", "kicker": "Tu turno", "h": "Ficha de análisis de obra", "body": "Continúa tu portfolio «La Navidad en el Siglo de Oro» con una ficha de análisis del cuadro trabajado en clase (Velázquez o El Greco).", "prompt": "Elabora una ficha con estos apartados: 1) título y autor de la obra; 2) descripción objetiva de la composición (quién está dónde); 3) análisis del uso de la luz y qué transmite; 4) tu interpretación personal: ¿qué mensaje sobre la Encarnación crees que el pintor quiso comunicar con estos recursos concretos?"}]},
  "eso2:Dic:3": {"title": "Tu propio villancico: escribir el nacimiento", "steps": [{"type": "hook", "kicker": "Taller de escritura", "h": "¿Te atreves a escribir como Lope?", "scenario": "Ya has leído a Lope de Vega y has analizado la pintura barroca. Ahora te toca a ti convertirte en poeta del Siglo de Oro por un día: contar, en verso, el nacimiento de Jesús.", "body": "Escribir un <b>poema narrativo</b> significa contar una historia en verso, con un principio, un desarrollo y un final, pero usando los recursos propios de la poesía: ritmo, imágenes, metáforas. No se trata de rimar por rimar, sino de construir una pequeña narración -el viaje a Belén, el nacimiento, la visita de los pastores- que además transmita una emoción o una idea, igual que hacía Lope de Vega en sus villancicos."}, {"type": "theory", "kicker": "Técnica poética", "h": "Cómo construir un poema narrativo de 14-16 versos", "body": "Un buen poema narrativo necesita <b>estructura</b> además de emoción. Puedes organizar tus 14-16 versos en tres partes: una <b>introducción</b> (2-4 versos que sitúen la escena: el viaje, la noche, Belén), un <b>desarrollo</b> (8-10 versos que narren el hecho central, el nacimiento, con alguna imagen sensorial: frío, luz, silencio, sonido) y un <b>cierre</b> (2-4 versos que dejen una reflexión o una imagen final memorable). Usa recursos como la <i>metáfora</i> (por ejemplo, comparar al Niño con la luz), el <i>epíteto</i> (adjetivos que resalten una cualidad) y cuida el <b>ritmo</b>: no hace falta rima perfecta, pero sí una musicalidad que se note al leerlo en voz alta.", "diagram": "INTRODUCCIÓN (2-4 versos) → sitúa el lugar y el momento <br> DESARROLLO (8-10 versos) → narra el nacimiento con imágenes sensoriales <br> CIERRE (2-4 versos) → reflexión o imagen final <br> RECURSOS → metáfora, epíteto, ritmo"}, {"type": "quiz", "kicker": "Comprueba", "h": "¿Qué es un poema narrativo?", "q": "¿Cuál de estas definiciones describe mejor un poema narrativo?", "opts": [{"t": "Un poema que cuenta una historia con principio, desarrollo y final, usando recursos poéticos", "ok": true}, {"t": "Un poema que solo describe un paisaje sin ninguna acción", "ok": false}, {"t": "Un texto en prosa que imita el ritmo de la poesía", "ok": false}, {"t": "Un poema que únicamente expresa los sentimientos del autor, sin contar nada", "ok": false}], "okMsg": "Así es. El poema narrativo cuenta algo -una historia con estructura- pero lo hace con el lenguaje propio de la poesía: verso, imágenes, ritmo. Por eso tu poema sobre el nacimiento de Jesús debe tener introducción, desarrollo y cierre, no solo emoción suelta.", "noMsg": "Repasa el diagrama: lo esencial del poema narrativo es que cuenta una historia (algo ocurre, hay una secuencia), y lo hace usando los recursos del verso, no solo describir o expresar sentimientos sueltos."}, {"type": "reflect", "kicker": "Tu turno", "h": "Escribe tu poema del Nacimiento", "body": "Es el momento de aportar tu propia pieza al portfolio «La Navidad en el Siglo de Oro»: un poema narrativo original.", "prompt": "Escribe un poema narrativo de entre 14 y 16 versos sobre el nacimiento de Jesús. Debe tener una introducción que sitúe la escena, un desarrollo que narre el hecho central con al menos una imagen sensorial (luz, frío, silencio o sonido) y un cierre con una reflexión o imagen final. Usa al menos una metáfora. Al terminar, subraya en tu propio texto la metáfora que has utilizado."}]},
  "eso2:Dic:4": {"title": "El Verbo se hizo carne: cierre del portfolio navideño", "steps": [{"type": "hook", "kicker": "Cierre del mes", "h": "¿Qué significa que una Palabra se convierta en persona?", "scenario": "Después de leer poesía y analizar pintura, llega el texto que da sentido a todo lo anterior: el prólogo del Evangelio de Juan, uno de los pasajes más profundos y más citados de toda la literatura religiosa universal.", "body": "Juan 1:1-14 no cuenta el nacimiento de Jesús con pastores ni pesebre, como hacen Lucas o Mateo: lo explica desde una perspectiva casi filosófica. Empieza con una frase que resuena con la propia idea de la creación: <i>«En el principio era el Verbo»</i>. La palabra griega original, <b>Logos</b>, significa a la vez 'palabra', 'razón' y 'sentido'. Juan afirma que ese Logos -esa Palabra eterna que ordena el universo- se convirtió en un ser humano concreto: Jesús de Nazaret. Esta semana cerramos el portfolio «La Navidad en el Siglo de Oro» conectando la poesía de Lope, el arte de Velázquez y el Greco, con el texto que los inspiró a todos: la Encarnación."}, {"type": "theory", "kicker": "Lectura teológica", "h": "El Verbo se hizo carne (Juan 1:1-14)", "body": "El prólogo de Juan construye su argumento en varios pasos. Primero afirma que el <b>Verbo</b> (Logos) existía «en el principio», junto a Dios y siendo Dios mismo: es decir, no es una idea creada, sino algo eterno. Después explica que por medio de ese Verbo «todas las cosas fueron hechas», vinculando la Encarnación con la propia creación del universo. El punto culminante llega en el versículo 14: <b>«Y el Verbo se hizo carne y habitó entre nosotros, lleno de gracia y de verdad»</b>. Esta frase es el corazón teológico de la Navidad: no se trata solo de que naciera un niño especial, sino de que lo eterno, lo divino, lo que 'ordena el sentido del mundo', se hizo visible, tocable, humano. Es exactamente el misterio que Lope intentaba expresar con su alegoría del pastor, y el que Velázquez y el Greco intentaban capturar con la luz sobre el pesebre: lo grande haciéndose pequeño y cercano.", "diagram": "EL VERBO (Logos) → existía desde el principio, es Dios <br> «TODAS LAS COSAS POR ÉL FUERON HECHAS» → el Verbo crea <br> «SE HIZO CARNE» (v.14) → lo eterno se vuelve humano y visible <br> CONEXIÓN → esto es lo que Lope narra en verso y Velázquez/El Greco pintan con luz"}, {"type": "quiz", "kicker": "Comprueba", "h": "¿Qué significa 'Verbo' en el prólogo de Juan?", "q": "Según Juan 1:1-14, ¿qué relación existe entre 'el Verbo' y Jesús?", "opts": [{"t": "El Verbo, que existía desde el principio junto a Dios, se hizo hombre en la persona de Jesús", "ok": true}, {"t": "El Verbo es solo un símbolo literario sin relación con Jesús", "ok": false}, {"t": "Jesús creó al Verbo cuando nació en Belén", "ok": false}, {"t": "El Verbo y Jesús son dos figuras completamente independientes", "ok": false}], "okMsg": "Correcto. Juan afirma que el Verbo (Logos), eterno y divino, es quien se hace carne en Jesús. Ese es el núcleo de la Encarnación: lo eterno se vuelve humano y concreto, el mismo misterio que has visto expresado en el poema de Lope y en la pintura barroca.", "noMsg": "Vuelve al diagrama: la clave está en el versículo 14. El Verbo no es un simple símbolo ni algo creado después; es eterno y, según Juan, se identifica con Jesús al 'hacerse carne'."}, {"type": "reflect", "kicker": "Tu turno", "h": "Reflexión final: lenguaje y Encarnación", "body": "Cierra tu portfolio «La Navidad en el Siglo de Oro» con la entrega final del mes: una reflexión que una todo lo trabajado.", "prompt": "Escribe una reflexión de al menos 15 líneas que responda a: 1) ¿Por qué crees que Juan elige la palabra 'Verbo' (Logos) en lugar de contar directamente la escena del pesebre, como hacen Lucas o Mateo? 2) Compara esta forma de contar la Encarnación con la de Lope de Vega (poesía) y la del cuadro que analizaste (pintura): ¿qué recurso -palabra, verso o imagen- te parece más eficaz para expresar el misterio de que 'lo divino se hace humano', y por qué? Cierra tu reflexión citando el versículo de Juan 1:14 completo."}]},
  "eso2:Feb:1": {"title": "El ocaso de un Imperio: los Austrias menores", "steps": [{"type": "hook", "kicker": "Historia de España", "h": "¿Cómo se hunde un imperio donde nunca se ponía el sol?", "scenario": "A comienzos del siglo XVII, España parece un gigante: un imperio con territorios en América, Europa y Asia. Sin embargo, en apenas cien años ese gigante empieza a tambalearse. Tres reyes -Felipe III, Felipe IV y Carlos II- presiden ese lento declive, conocidos como los Austrias menores.", "body": "El siglo XVII español es un siglo de <b>contrastes brutales</b>: mientras el Imperio pierde poder político y militar frente a Francia, Inglaterra y las Provincias Unidas, su cultura vive uno de sus momentos más brillantes con el Barroco. Para entender ese contraste, primero necesitamos ordenar los hechos: ¿qué pasó, en qué orden, y por qué se habla de 'decadencia'? Esta semana construyes una línea de tiempo con los eventos políticos clave de este proceso."}, {"type": "theory", "kicker": "Contexto histórico", "h": "Los Austrias menores y la crisis del Imperio", "body": "Se llama <b>Austrias menores</b> a los tres últimos reyes de la dinastía Habsburgo en España: <b>Felipe III</b> (1598-1621), <b>Felipe IV</b> (1621-1665) y <b>Carlos II</b> (1665-1700), en contraste con los 'Austrias mayores' (Carlos V y Felipe II), de mayor poder efectivo. Durante este periodo, el gobierno recae con frecuencia en <i>validos</i> -ministros todopoderosos como el Duque de Lerma o el Conde-Duque de Olivares- mientras el poder militar español se desgasta en guerras larguísimas, especialmente la <b>Guerra de los Treinta Años</b> (1618-1648) y los conflictos con Francia. La derrota en batallas clave, la pérdida de Portugal (1640-1668) y la firma de tratados desfavorables como la <b>Paz de Westfalia</b> (1648) o la <b>Paz de los Pirineos</b> (1659) marcan hitos de un declive que culmina con un rey, Carlos II, física y políticamente débil, sin descendencia, lo que abre una grave crisis sucesoria.", "diagram": "1598 FELIPE III → validos, expulsión de los moriscos (1609) <br> 1618-1648 GUERRA DE LOS TREINTA AÑOS → desgaste militar y económico <br> 1640 SUBLEVACIÓN DE CATALUÑA Y PORTUGAL → crisis interna del Imperio <br> 1659 PAZ DE LOS PIRINEOS → España cede territorio y hegemonía a Francia <br> 1665-1700 CARLOS II → decadencia final, sin heredero"}, {"type": "quiz", "kicker": "Comprueba", "h": "¿Quiénes son los Austrias menores?", "q": "¿Qué reyes forman el grupo conocido como los 'Austrias menores' y qué caracteriza su reinado?", "opts": [{"t": "Felipe III, Felipe IV y Carlos II, un periodo marcado por el gobierno de validos y la pérdida de poder del Imperio", "ok": true}, {"t": "Carlos V y Felipe II, un periodo de máxima expansión territorial", "ok": false}, {"t": "Los Reyes Católicos, que unificaron España en el siglo XV", "ok": false}, {"t": "Felipe V y Carlos III, ya en el siglo XVIII con la dinastía Borbón", "ok": false}], "okMsg": "Correcto. Felipe III, Felipe IV y Carlos II son los Austrias menores: un periodo en el que el poder real se apoya en validos y el Imperio, tras el esplendor de los Austrias mayores, empieza a perder territorio y hegemonía frente a otras potencias europeas.", "noMsg": "Revisa el diagrama: los Austrias menores son los tres últimos Habsburgo españoles del siglo XVII (Felipe III, Felipe IV, Carlos II), no los reyes de máxima expansión ni los de otra dinastía posterior."}, {"type": "reflect", "kicker": "Tu turno", "h": "Construye tu línea de tiempo", "body": "Inicia el trabajo «El Barroco español: arte y decadencia» con la primera entrega: una línea de tiempo histórica.", "prompt": "Elabora una línea de tiempo con al menos 6 hitos del siglo XVII español (por ejemplo: subida al trono de Felipe III, Guerra de los Treinta Años, sublevación de Cataluña y Portugal, Paz de los Pirineos, reinado de Carlos II, y algún otro que hayáis visto en clase). Para cada hito, escribe una frase explicando por qué contribuye a la idea de 'decadencia' del Imperio."}]},
  "eso2:Feb:2": {"title": "Pintar la crisis: el Barroco de Ribera y Murillo", "steps": [{"type": "hook", "kicker": "Arte y sociedad", "h": "¿Puede un cuadro ser una respuesta a una crisis?", "scenario": "Mientras el Imperio pierde guerras y territorios, los pintores españoles del siglo XVII producen algunas de las obras más intensas de la historia del arte europeo. José de Ribera y Bartolomé Esteban Murillo retratan mendigos, santos y escenas cotidianas con un realismo que a veces resulta incómodo.", "body": "El <b>Barroco español</b> no es un arte de evasión frente a la crisis, sino, en muchos sentidos, una respuesta directa a ella. Ribera pinta cuerpos ancianos, heridas, texturas de piel envejecida con un realismo casi brutal (el llamado <i>tenebrismo</i>, herencia de Caravaggio); Murillo, en cambio, retrata niños pobres y escenas religiosas con una luz más suave y una ternura que humaniza la pobreza sin ocultarla. Ambos, desde estilos distintos, convierten el sufrimiento y la debilidad en materia artística de primer nivel."}, {"type": "theory", "kicker": "Análisis de obra", "h": "Cómo leer un cuadro de Ribera o Murillo", "body": "Para analizar una pintura barroca de Ribera o Murillo debes observar: la <b>composición</b> (qué elementos ocupan el centro, cómo se organiza el espacio), el <b>uso de la luz</b> (el tenebrismo de Ribera crea contrastes muy fuertes que dramatizan el sufrimiento; la luz de Murillo suele ser más difusa y cálida, generando cercanía emocional), el <b>tratamiento de los personajes</b> (¿son santos idealizados o gente común, con arrugas y ropa remendada?) y el <b>mensaje social o religioso</b> que se desprende de esas decisiones. En ambos pintores, la pobreza y la debilidad humana no se esconden: se muestran con dignidad, como si el arte quisiera decir que hay grandeza incluso en la miseria de una época en crisis.", "diagram": "RIBERA → tenebrismo intenso, cuerpos envejecidos, dramatismo <br> MURILLO → luz cálida y difusa, niños pobres, ternura <br> COMPOSICIÓN → qué ocupa el centro, cómo se organiza el espacio <br> MENSAJE → dignidad en medio de la pobreza y la crisis del siglo XVII"}, {"type": "quiz", "kicker": "Comprueba", "h": "¿Cómo responde el Barroco a la crisis del XVII?", "q": "¿Cuál de estas afirmaciones describe mejor la relación entre el Barroco español y la crisis del siglo XVII?", "opts": [{"t": "El Barroco retrata con crudeza o ternura la pobreza y el sufrimiento, dándoles dignidad artística en plena crisis", "ok": true}, {"t": "El Barroco ignora completamente la crisis y solo pinta escenas de lujo y riqueza", "ok": false}, {"t": "El Barroco español copia exactamente el estilo renacentista italiano sin ninguna novedad", "ok": false}, {"t": "El Barroco desaparece durante el siglo XVII por falta de encargos", "ok": false}], "okMsg": "Correcto. Lejos de evadirse, pintores como Ribera y Murillo convierten la pobreza, la vejez o la infancia humilde en protagonistas de sus cuadros, dándoles una dignidad artística que responde, a su manera, a la crisis social y económica del Imperio.", "noMsg": "Piensa en el diagrama: ni Ribera ni Murillo pintan escenas de lujo ni copian sin más el Renacimiento; ambos muestran, cada uno con su estilo, la pobreza y la fragilidad humana con dignidad, como respuesta artística a una época difícil."}, {"type": "reflect", "kicker": "Tu turno", "h": "Ficha de análisis: Ribera o Murillo", "body": "Continúa el trabajo «El Barroco español: arte y decadencia» con el análisis de una obra concreta.", "prompt": "Elige un cuadro de Ribera o Murillo trabajado en clase y elabora una ficha con: 1) título, autor y fecha; 2) descripción de la composición y los personajes; 3) análisis del uso de la luz (tenebrismo o luz cálida) y qué efecto produce; 4) tu interpretación: ¿qué crees que el pintor quiere decir sobre la sociedad de su época a través de esta obra?"}]},
  "eso2:Feb:3": {"title": "Todo es vanidad: el Eclesiastés y el desengaño barroco", "steps": [{"type": "hook", "kicker": "Sabiduría bíblica", "h": "¿Y si todo lo que construyes se desvanece?", "scenario": "Un rey rico, sabio y poderoso -tradicionalmente identificado con Salomón- mira hacia atrás, hacia todo lo que ha construido: palacios, jardines, riquezas, sabiduría. Y llega a una conclusión inquietante: nada de eso llena el vacío. 'Todo es vanidad y correr tras el viento.'", "body": "El libro de <b>Eclesiastés</b> es uno de los textos más desafiantes de la Biblia: no ofrece consuelos fáciles, sino una reflexión honesta sobre los límites del placer, la riqueza y el éxito humano. En Eclesiastés 2:11-12 el autor examina todo lo que ha logrado y concluye que es <i>'vanidad'</i> -en hebreo, <i>hebel</i>, literalmente 'vapor' o 'aliento', algo que se desvanece en cuanto intentas atraparlo-. Esta semana vamos a conectar ese desengaño bíblico con el <b>desengaño barroco</b>, una de las ideas centrales de la cultura española del siglo XVII."}, {"type": "theory", "kicker": "Teología y cultura", "h": "La 'vanidad' bíblica y el 'desengaño' barroco", "body": "En Eclesiastés 2:11-12 el autor escribe: <b>«Me dediqué a considerar la sabiduría: vi que también esto era vanidad»</b>. La palabra hebrea <i>hebel</i> (vanidad) no significa vanidad en el sentido moderno de 'presumir', sino algo que es pasajero, que no perdura, como el vapor que se disuelve en el aire. El Barroco español del siglo XVII convierte esta misma idea en un tema artístico y filosófico central llamado <b>desengaño</b>: la conciencia de que la riqueza, la belleza y el poder son pasajeros, especialmente urgente en una sociedad que vive la crisis y el declive de un Imperio. Este desengaño aparece en pinturas de <i>vanitas</i> (bodegones con calaveras, relojes y flores marchitas), en la poesía de Quevedo o Góngora, y explica por qué el arte barroco, en plena decadencia política, se obsesiona con la fugacidad del tiempo y la muerte.", "diagram": "ECLESIASTÉS 2:11-12 → 'todo es vanidad' (hebel = vapor, algo pasajero) <br> DESENGAÑO BARROCO → conciencia de que riqueza y poder se desvanecen <br> ARTE VANITAS → calaveras, relojes, flores marchitas como símbolo <br> CONEXIÓN → la crisis del Imperio del s.XVII da urgencia a esta reflexión"}, {"type": "quiz", "kicker": "Comprueba", "h": "¿Qué significa 'vanidad' en Eclesiastés?", "q": "En el contexto de Eclesiastés 2:11-12, ¿qué significa la palabra 'vanidad' (hebel)?", "opts": [{"t": "Algo pasajero y fugaz, como el vapor, que no perdura por mucho que se persiga", "ok": true}, {"t": "El orgullo de presumir de las propias riquezas ante los demás", "ok": false}, {"t": "Un elogio a la sabiduría como el bien más duradero que existe", "ok": false}, {"t": "Una crítica exclusivamente dirigida a los pobres de la sociedad", "ok": false}], "okMsg": "Correcto. 'Hebel' significa literalmente vapor o aliento: algo que se disuelve en cuanto intentas retenerlo. Por eso Eclesiastés concluye que la riqueza, el placer o incluso la sabiduría humana, sin más, no llenan ni perduran, una idea que el Barroco español retoma como 'desengaño'.", "noMsg": "Vuelve al diagrama: 'vanidad' aquí no es presumir ni un elogio a la sabiduría sin matices; es la idea de algo pasajero, como el vapor, que se desvanece por mucho que el ser humano intente aferrarse a ello."}, {"type": "reflect", "kicker": "Tu turno", "h": "El Barroco responde a la vanidad", "body": "Sigue construyendo el trabajo «El Barroco español: arte y decadencia» con una reflexión que une teología y arte.", "prompt": "Redacta una reflexión de al menos 12 líneas respondiendo a: 1) ¿Qué quiere decir Eclesiastés 2:11-12 cuando afirma que 'todo es vanidad'? 2) ¿Por qué crees que una sociedad en crisis, como la España del siglo XVII, encuentra especialmente convincente esta idea? 3) Relaciona esta reflexión con el cuadro de Ribera o Murillo que analizaste la semana pasada: ¿hay en él algún elemento que hable de la fugacidad de la vida o de la riqueza? Cierra citando el versículo de Eclesiastés 2:12 completo."}]},
  "eso2:Feb:4": {"title": "Carlos II, 'el Hechizado': el rey del final", "steps": [{"type": "hook", "kicker": "Cierre del mes", "h": "¿Cómo se cierra el ciclo de un imperio?", "scenario": "En 1665 sube al trono un niño de apenas cuatro años, enfermizo y débil, apodado siglos después 'el Hechizado'. Su reinado, el más largo de los Austrias menores, es también el más simbólico del declive: España pierde territorios, la economía se hunde y el propio rey, sin descendencia, deja el trono en el aire.", "body": "El reinado de <b>Carlos II</b> (1665-1700) cierra el ciclo de los Austrias menores que empezaste a estudiar en la semana 1. Es el momento en que la <b>decadencia política</b> -guerras perdidas, hacienda arruinada, territorios cedidos- coincide con la etapa de mayor esplendor del <b>Barroco</b> en la pintura, la literatura y el arte religioso. Esta semana lees un texto adaptado sobre su reinado y cierras el trabajo «El Barroco español: arte y decadencia» uniendo todo lo trabajado este mes: historia, arte y el desengaño bíblico de Eclesiastés."}, {"type": "theory", "kicker": "Lectura histórica", "h": "El reinado de Carlos II y el final de una dinastía", "body": "Carlos II heredó un imperio ya debilitado y, según los textos históricos, sufrió problemas de salud graves durante toda su vida, lo que alimentó leyendas sobre supuestos 'hechizos', de ahí su apodo. Durante su reinado se firmaron nuevas paces desfavorables, la Hacienda real estuvo al borde de la bancarrota y la ausencia de un heredero directo provocó una gravísima <b>crisis sucesoria</b> que, tras su muerte en 1700, desembocaría en la Guerra de Sucesión Española y el fin de la dinastía de los Austrias en España. El <b>tono</b> con el que los textos de la época y los historiadores describen este reinado suele ser de lamento o de constatación de un final inevitable: no hay grandes batallas ni conquistas que narrar, sino administración de la escasez y espera de un desenlace. Es, en cierto modo, la versión política de la 'vanidad' de Eclesiastés: el esplendor y el poder que el Imperio creyó eterno se revelan, con el paso de las décadas, tan pasajeros como el vapor.", "diagram": "1665 → Carlos II sube al trono con 4 años, salud frágil <br> REINADO → hacienda arruinada, paces desfavorables, sin heredero <br> TONO DE LOS TEXTOS → lamento, constatación de un final inevitable <br> 1700 → muerte de Carlos II, fin de los Austrias, crisis sucesoria <br> CONEXIÓN → el poder del Imperio también fue 'vanidad', vapor que se desvanece"}, {"type": "quiz", "kicker": "Comprueba", "h": "¿Qué representa el reinado de Carlos II?", "q": "¿Qué consecuencia histórica clave tuvo la falta de descendencia de Carlos II?", "opts": [{"t": "Una grave crisis sucesoria que, tras su muerte, condujo a la Guerra de Sucesión Española y al fin de los Austrias", "ok": true}, {"t": "El fortalecimiento inmediato del Imperio español en América", "ok": false}, {"t": "La firma de tratados que devolvieron a España todo el territorio perdido", "ok": false}, {"t": "La coronación automática de su hermano mayor sin ningún conflicto", "ok": false}], "okMsg": "Correcto. Al morir Carlos II sin descendencia en 1700, se desató una crisis sucesoria que terminó en la Guerra de Sucesión Española y en el final de la dinastía de los Austrias en el trono español, el desenlace lógico del proceso de decadencia que has estudiado todo el mes.", "noMsg": "Repasa el diagrama: la falta de heredero no fortaleció el Imperio ni devolvió territorios; al contrario, provocó una crisis sucesoria gravísima que desembocó en una guerra y en el cambio de dinastía."}, {"type": "reflect", "kicker": "Tu turno", "h": "Cierre del trabajo: analiza el tono", "body": "Entrega final del trabajo «El Barroco español: arte y decadencia», uniendo historia, arte y reflexión bíblica de todo el mes.", "prompt": "A partir del texto adaptado sobre el reinado de Carlos II, escribe un análisis de al menos 15 líneas que responda a: 1) ¿Qué tono predomina en el texto (lamento, resignación, crítica) y con qué palabras o expresiones concretas lo identificas? 2) ¿Por qué crees que el esplendor artístico del Barroco (Ribera, Murillo) convive con la decadencia política que representa Carlos II? 3) Conecta esta paradoja con Eclesiastés 2:12 ('Me dediqué a considerar la sabiduría: vi que también esto era vanidad'): ¿en qué sentido el propio Imperio español del siglo XVII fue también, a su manera, una demostración de que 'todo es vanidad'?"}]},
  "eso2:Mar:1": {"title": "Quevedo: la pluma que no perdona", "steps": [{"type": "hook", "kicker": "Barroco en carne viva", "h": "¿Puede un mismo poeta hacerte llorar, rezar y reír en tres poemas distintos?", "scenario": "Es Madrid, siglo XVII. España vive de apariencias: la nobleza se arruina en secreto, la Iglesia discute sobre el alma, y en las tabernas se ríen del rico avaricioso. Un solo hombre, con una pluma afilada como una espada, escribe sobre los tres mundos a la vez.", "body": "Ese hombre es <b>Francisco de Quevedo</b>, maestro del <b>conceptismo</b> (ingenio, juegos de palabras, ideas condensadas). Sus sonetos se dividen en tres grandes temas: los <b>morales</b> (la vida, el tiempo, la muerte), los <b>espirituales</b> (la relación del alma con Dios) y los <b>satíricos</b> (la crítica social, casi siempre feroz y con humor negro)."}, {"type": "theory", "kicker": "Tres registros, un mismo genio", "h": "Moral, espiritual y satírico: no es lo mismo hablar de la muerte que reírse del dinero", "body": "En el <b>soneto moral</b>, Quevedo medita sobre el paso del tiempo y la fragilidad humana: la vida se le escapa de las manos como arena. En el <b>soneto espiritual</b>, el poeta se dirige a Dios o reflexiona sobre el alma, la culpa y la salvación, con un tono íntimo y a veces angustiado. En el <b>soneto satírico</b>, cambia radicalmente el tono: usa la ironía, el doble sentido y hasta la caricatura para atacar vicios como la avaricia, la hipocresía o la vanidad de su época.", "diagram": "<b>Quevedo, conceptista</b><br>Moral → tiempo, muerte, vida breve<br>Espiritual → alma, Dios, culpa<br>Satírico → ironía, crítica social, humor negro<br>Un mismo autor, tres máscaras distintas"}, {"type": "quiz", "kicker": "Comprueba el registro", "h": "¿Qué tipo de soneto es este?", "q": "Un soneto de Quevedo que se burla, con ironía mordaz, de un noble que finge riqueza para aparentar ante la sociedad. ¿A qué tipo pertenece?", "opts": [{"t": "Satírico", "ok": true}, {"t": "Espiritual", "ok": false}, {"t": "Moral", "ok": false}, {"t": "Amoroso puro, sin crítica alguna", "ok": false}], "okMsg": "Exacto: la crítica social con ironía es la marca del Quevedo satírico.", "noMsg": "Piénsalo de nuevo: aquí no hay meditación sobre Dios ni sobre el tiempo, sino burla directa a un vicio social."}, {"type": "reflect", "kicker": "Tu turno de leer como un filólogo", "h": "Lee y clasifica los tres sonetos de Quevedo trabajados en clase", "body": "Vas a leer los tres sonetos de Quevedo asignados esta semana (uno moral, uno espiritual y uno satírico) y vas a identificar el tema central de cada uno, apoyándote en al menos un verso como cita textual.", "prompt": "Para cada uno de los tres sonetos, escribe: 1) el tipo (moral / espiritual / satírico), 2) el tema en una frase, 3) un verso citado que lo demuestre, 4) una palabra o imagen que te haya impactado y por qué."}]},
  "eso2:Mar:2": {"title": "Góngora: la belleza que se hace esperar", "steps": [{"type": "hook", "kicker": "El otro genio del Barroco", "h": "¿Y si un poema estuviera hecho para no entenderse a la primera?", "scenario": "Mientras Quevedo afila la ironía, en Córdoba otro poeta construye versos tan cargados de imágenes y cultismos que sus contemporáneos necesitaban comentarios para descifrarlos. No escribía para todos: escribía para los que quisieran esforzarse.", "body": "Ese poeta es <b>Luis de Góngora</b>, cabeza visible del <b>culteranismo</b>: una poesía que persigue la belleza a través de un lenguaje difícil, sensorial y elaborado, casi como un cuadro hecho de palabras."}, {"type": "theory", "kicker": "Conceptismo vs. culteranismo", "h": "Góngora frente a Quevedo: dos formas de complicar el lenguaje", "body": "Si Quevedo condensa ideas con ingenio (conceptismo: pocas palabras, mucho significado), Góngora hace lo contrario: multiplica adjetivos, cultismos (palabras cultas tomadas del latín), hipérbatos (orden alterado de la frase) y metáforas sensoriales para crear una <b>belleza difícil</b>, casi musical. Leer a Góngora exige pararse en cada verso, casi traducirlo. No busca que entiendas rápido: busca que te deleites despacio.", "diagram": "<b>Culteranismo (Góngora)</b><br>Cultismos + hipérbaton + metáfora sensorial<br>= belleza difícil, para saborear<br><br><b>Conceptismo (Quevedo)</b><br>Ingenio + juego de ideas<br>= significado denso, para pensar"}, {"type": "quiz", "kicker": "Detective de vocabulario", "h": "¿Qué recurso es propio del culteranismo de Góngora?", "q": "Un verso que altera el orden normal de la frase y usa palabras cultas de origen latino para crear una imagen sensorial muy elaborada, ¿qué rasgo del estilo de Góngora está usando?", "opts": [{"t": "Hipérbaton y cultismos", "ok": true}, {"t": "Ironía satírica sobre el dinero", "ok": false}, {"t": "Lenguaje coloquial y directo", "ok": false}, {"t": "Ausencia total de adjetivos", "ok": false}], "okMsg": "Correcto: el hipérbaton y los cultismos son la firma del culteranismo gongorino.", "noMsg": "Revisa la teoría: el culteranismo se reconoce por el orden alterado de la frase y el vocabulario culto, no por la ironía."}, {"type": "reflect", "kicker": "Comparar para comprender", "h": "Lee el soneto de Góngora y compáralo con los de Quevedo", "body": "Vas a leer el soneto de Góngora asignado esta semana y a compararlo directamente con los sonetos de Quevedo que ya conoces, buscando diferencias concretas de vocabulario y estilo.", "prompt": "Escribe una comparación breve: 1) copia dos versos de Góngora con vocabulario culto y explica su significado con tus palabras, 2) señala una diferencia clara entre el estilo de Góngora y el de Quevedo, 3) responde: ¿cuál de los dos estilos te exige más esfuerzo como lector, y por qué?"}]},
  "eso2:Mar:3": {"title": "El soneto por dentro: catorce versos, ninguna casualidad", "steps": [{"type": "hook", "kicker": "La arquitectura del poema", "h": "¿Por qué un soneto tiene siempre 14 versos y no 13 ni 15?", "scenario": "Un arquitecto no construye un edificio al azar: cada columna, cada viga, tiene una función. Los poetas del Barroco pensaban igual sobre el soneto: una forma tan estricta que, si la dominas, puedes construir con ella casi cualquier idea.", "body": "Esta semana no leerás el soneto solo por su contenido, sino por su <b>estructura métrica</b>: la forma exacta que Quevedo y Góngora respetaron incluso cuando decían cosas completamente distintas."}, {"type": "theory", "kicker": "Anatomía del soneto", "h": "2 cuartetos + 2 tercetos: la fórmula que no falla", "body": "El soneto clásico español tiene <b>14 versos endecasílabos</b> (de 11 sílabas), organizados en <b>dos cuartetos</b> (estrofas de 4 versos, normalmente con rima ABBA ABBA) y <b>dos tercetos</b> (estrofas de 3 versos, con esquemas de rima variables como CDC DCD). Los cuartetos suelen plantear una idea o imagen; los tercetos la desarrollan, la contradicen o la resuelven, muchas veces con un giro final sorprendente.", "diagram": "<b>SONETO = 14 versos</b><br>Cuarteto 1 (4 versos) → plantea<br>Cuarteto 2 (4 versos) → insiste<br>Terceto 1 (3 versos) → gira<br>Terceto 2 (3 versos) → resuelve<br>Total: 2 cuartetos + 2 tercetos, rima marcada"}, {"type": "quiz", "kicker": "Cuenta y comprueba", "h": "¿Cuál es la estructura correcta de un soneto?", "q": "¿Cómo se organiza correctamente un soneto clásico español?", "opts": [{"t": "2 cuartetos + 2 tercetos (14 versos en total)", "ok": true}, {"t": "3 cuartetos + 1 terceto (15 versos en total)", "ok": false}, {"t": "1 cuarteto + 3 tercetos (13 versos en total)", "ok": false}, {"t": "4 tercetos (12 versos en total)", "ok": false}], "okMsg": "Correcto: 2 cuartetos y 2 tercetos suman los 14 versos característicos del soneto.", "noMsg": "Repasa el diagrama: la estructura fija es 2 cuartetos (4+4) más 2 tercetos (3+3) = 14 versos."}, {"type": "reflect", "kicker": "Diseca un soneto", "h": "Verifica la métrica en uno de los poemas trabajados", "body": "Elige uno de los sonetos que ya has leído (de Quevedo o de Góngora) y comprueba, verso a verso, que cumple la estructura de 2 cuartetos y 2 tercetos.", "prompt": "Copia el soneto elegido y numera sus 14 versos. Marca con corchetes dónde empieza cada cuarteto y cada terceto. Señala la rima de cada verso (A, B, C...) y explica en dos frases qué idea aporta cada cuarteto y qué giro aportan los tercetos."}]},
  "eso2:Mar:4": {"title": "Tu propio soneto: fe, tiempo o esperanza", "steps": [{"type": "hook", "kicker": "De lector a poeta", "h": "¿Serías capaz de decir algo verdadero en solo 14 versos?", "scenario": "Has leído a Quevedo hablar del tiempo que se escapa, a Góngora construir belleza con palabras difíciles, y has diseccionado la métrica del soneto como quien abre un reloj para ver sus engranajes. Ahora te toca a ti montar el mecanismo.", "body": "Esta semana cierras el <b>Portfolio poético 'El Barroco lírico'</b> escribiendo tu propio soneto de 14 versos sobre <b>fe, tiempo o esperanza</b>, los mismos temas que obsesionaban a los poetas barrocos."}, {"type": "theory", "kicker": "Una palabra para acompañarte", "h": "Cuando las palabras importan: el versículo de esta semana", "body": "Los poetas barrocos cuidaban cada palabra como si fuera la última que fueran a pronunciar. El rey David expresa una idea muy parecida en el Salmo 19:14: <b>«Sean gratos los dichos de mi boca y la meditación de mi corazón delante de ti»</b>. Antes de escribir tu soneto, piensa que un poema no es solo técnica: es también lo que de verdad llevas dentro, puesto en palabras cuidadas.", "diagram": "<b>Salmo 19:14</b><br>\"Sean gratos los dichos de mi boca<br>y la meditación de mi corazón<br>delante de ti\"<br><br>Palabras + corazón = poesía con sentido"}, {"type": "quiz", "kicker": "Última comprobación técnica", "h": "Antes de escribir, repasa la regla de oro", "q": "Tu soneto sobre fe, tiempo o esperanza, para ser correcto formalmente, debe tener...", "opts": [{"t": "14 versos organizados en 2 cuartetos y 2 tercetos", "ok": true}, {"t": "10 versos libres sin ninguna estructura", "ok": false}, {"t": "Solo 2 tercetos, sin cuartetos", "ok": false}, {"t": "20 versos con rima libre", "ok": false}], "okMsg": "Así es: por muy personal que sea tu tema, la forma del soneto exige 14 versos en 2 cuartetos y 2 tercetos.", "noMsg": "Recuerda la semana anterior: la estructura fija del soneto es 2 cuartetos + 2 tercetos, 14 versos en total."}, {"type": "reflect", "kicker": "Cierra tu portfolio poético", "h": "Escribe tu soneto y complétalo con el Salmo 19:14", "body": "Escribe un soneto propio de 14 versos (respetando, en la medida de lo posible, la estructura de 2 cuartetos y 2 tercetos) sobre <b>fe, tiempo o esperanza</b>, inspirándote en el estilo de Quevedo o de Góngora.", "prompt": "Escribe tu soneto completo de 14 versos. Después, en un párrafo aparte, explica: 1) qué tema elegiste y por qué, 2) qué recurso estilístico de Quevedo o Góngora intentaste imitar, 3) cómo se relaciona tu poema con la idea del Salmo 19:14 sobre cuidar lo que decimos."}]},
  "eso2:Abr:1": {"title": "Jovellanos: la razón al servicio de la tierra", "steps": [{"type": "hook", "kicker": "Un siglo que quiere cambiarlo todo", "h": "¿Puede un texto escrito hace 250 años seguir teniendo razón hoy?", "scenario": "España, finales del siglo XVIII. El campo apenas produce lo necesario, muchas tierras están en manos de unos pocos y la educación llega a muy pocos. Un hombre, jurista y pensador, decide escribir un informe detallado explicando qué está fallando y cómo arreglarlo.", "body": "Ese hombre es <b>Gaspar Melchor de Jovellanos</b>, una de las figuras centrales de la <b>Ilustración española</b>: un movimiento que defendía la razón, la educación y las reformas prácticas para mejorar la vida de la gente."}, {"type": "theory", "kicker": "Reformar sin romper", "h": "La Ilustración española: Feijoo y Jovellanos", "body": "La Ilustración en España tuvo dos grandes voces: el fraile <b>Benito Jerónimo Feijoo</b>, que combatió la superstición y defendió el uso de la razón y la observación, y <b>Jovellanos</b>, que llevó esas ideas al terreno práctico: reforma agraria, mejora de la educación, impulso de la economía. A diferencia de otros ilustrados europeos más radicales, muchos pensadores españoles buscaron conciliar la razón ilustrada con la fe cristiana, sin renunciar a ninguna de las dos.", "diagram": "<b>Ilustración española</b><br>Feijoo → razón contra superstición<br>Jovellanos → reforma agraria y educativa<br>Objetivo: mejorar la sociedad con argumentos, no con dogmas"}, {"type": "quiz", "kicker": "Identifica la propuesta", "h": "¿Cuál era el objetivo principal de las reformas de Jovellanos?", "q": "En su famoso informe sobre la agricultura, ¿qué buscaba principalmente Jovellanos?", "opts": [{"t": "Mejorar la producción de la tierra y las condiciones económicas mediante reformas racionales", "ok": true}, {"t": "Eliminar por completo la fe cristiana de la vida pública", "ok": false}, {"t": "Restaurar los fueros medievales de cada reino", "ok": false}, {"t": "Prohibir la educación a la mayoría de la población", "ok": false}], "okMsg": "Exacto: Jovellanos proponía reformas prácticas y racionales, sobre todo en el campo y la educación.", "noMsg": "Revisa la teoría: Jovellanos no atacaba la fe, buscaba reformas económicas y educativas basadas en la razón."}, {"type": "reflect", "kicker": "Lee como un reformador", "h": "Analiza el fragmento adaptado de Jovellanos", "body": "Lee el fragmento adaptado de un texto de Jovellanos trabajado en clase e identifica con precisión qué problema denuncia y qué solución propone.", "prompt": "Responde por escrito: 1) ¿qué problema concreto señala Jovellanos en el fragmento?, 2) ¿qué reforma propone para solucionarlo?, 3) ¿crees que ese tipo de razonamiento (observar un problema, argumentar y proponer una solución) sigue siendo útil hoy? Pon un ejemplo actual."}]},
  "eso2:Abr:2": {"title": "Razón y fe: ¿aliadas o enemigas?", "steps": [{"type": "hook", "kicker": "El gran debate del XVIII", "h": "¿Puede alguien confiar en la ciencia y en Dios al mismo tiempo?", "scenario": "En los salones y universidades del siglo XVIII se discute con pasión: unos pensadores creen que la razón debe sustituir poco a poco a la religión; otros, como Feijoo, creen que la razón bien usada en realidad confirma y purifica la fe, alejándola de supersticiones.", "body": "Esta semana entras tú en ese debate: <b>¿son la razón y la fe aliadas o enemigas en la España del siglo XVIII?</b> No hay una única respuesta correcta y aceptada por todos; hay argumentos serios en varias direcciones, y tu tarea es entenderlos con honestidad."}, {"type": "theory", "kicker": "Dos posturas, muchos matices", "h": "Tensión entre fe e Ilustración", "body": "Algunos ilustrados europeos defendían una razón totalmente separada de la religión, e incluso crítica con ella. En España, en cambio, gran parte de los ilustrados (como Feijoo, sacerdote benedictino) entendían la razón como una herramienta para <b>purificar la fe de supersticiones</b>, no para eliminarla: usaban la observación y el argumento para combatir creencias sin fundamento, mientras seguían siendo hombres de fe. Otros sectores, más conservadores, desconfiaban de cualquier uso de la razón que pudiera poner en duda la autoridad religiosa. Comprender el siglo XVIII exige ver estos matices, no reducirlo a un choque simple de \"ciencia contra religión\".", "diagram": "<b>Postura A</b>: razón y fe se oponen, la razón debe imponerse<br><b>Postura B</b>: razón y fe se necesitan, la razón purifica la fe (Feijoo)<br><b>Postura C</b>: la razón amenaza la autoridad religiosa y debe limitarse<br>→ Ninguna es \"la verdad oficial\": son posturas históricas a debatir"}, {"type": "quiz", "kicker": "Antes del debate", "h": "¿Cómo entendía Feijoo la relación entre razón y fe?", "q": "Según lo estudiado, ¿cuál describe mejor la postura de Feijoo?", "opts": [{"t": "Usaba la razón para combatir la superstición, sin renunciar a su fe cristiana", "ok": true}, {"t": "Rechazaba cualquier uso de la razón por ser peligroso para la fe", "ok": false}, {"t": "Defendía que la fe debía desaparecer por completo de la sociedad", "ok": false}, {"t": "No tenía ninguna opinión sobre religión ni ciencia", "ok": false}], "okMsg": "Correcto: Feijoo combinaba razón crítica y fe cristiana, atacando la superstición, no la religión.", "noMsg": "Repasa la teoría: Feijoo era sacerdote y usaba la razón para purificar la fe, no para eliminarla."}, {"type": "reflect", "kicker": "Debate con matices", "h": "Prepara tu argumento para el debate en clase", "body": "Vas a preparar una postura argumentada, con matices, sobre si la razón y la fe fueron aliadas o enemigas en la España del siglo XVIII, para el debate en clase.", "prompt": "Escribe tu posición: 1) elige una postura (aliadas, enemigas o \"depende\") y defiéndela con al menos dos argumentos basados en Feijoo o Jovellanos, 2) reconoce honestamente un argumento fuerte de la postura contraria, 3) explica con tus palabras un matiz que hayas descubierto y que no sabías antes de esta sesión."}]},
  "eso2:Abr:3": {"title": "Nueva Planta: el mapa de España cambia para siempre", "steps": [{"type": "hook", "kicker": "Un decreto, un país distinto", "h": "¿Qué pasa cuando un rey decide que todos los territorios deben gobernarse igual?", "scenario": "Tras años de guerra por el trono de España, Felipe V, ya victorioso, se enfrenta a una decisión enorme: ¿mantiene las leyes e instituciones propias que durante siglos tuvieron Cataluña, Aragón y Valencia, o impone un modelo único para todo el reino?", "body": "Felipe V elige la segunda opción con los <b>Decretos de Nueva Planta (1716)</b>: una reforma que cambia el mapa institucional de España de forma definitiva."}, {"type": "theory", "kicker": "Un solo modelo para toda España", "h": "Los Decretos de Nueva Planta (1716)", "body": "Con los <b>Decretos de Nueva Planta</b>, Felipe V suprimió los <b>fueros</b> (leyes e instituciones propias) que Cataluña, Aragón y Valencia habían mantenido durante siglos, e impuso un modelo administrativo unificado basado en el de Castilla. Esto supuso, entre otros cambios, la desaparición de instituciones propias de gobierno en esos territorios y la extensión de leyes y administración castellanas. El objetivo de Felipe V era construir un Estado más centralizado y uniforme, algo característico del absolutismo del siglo XVIII.", "diagram": "<b>Antes de 1716</b><br>Cataluña, Aragón, Valencia → fueros e instituciones propias<br><br><b>Después de 1716 (Nueva Planta)</b><br>Administración unificada según el modelo castellano<br>Fin de los fueros propios de esos territorios"}, {"type": "quiz", "kicker": "Comprueba el cambio", "h": "¿Qué supusieron los Decretos de Nueva Planta para Cataluña, Aragón y Valencia?", "q": "¿Cuál fue el efecto principal de los Decretos de Nueva Planta de 1716 sobre estos territorios?", "opts": [{"t": "La supresión de sus fueros e instituciones propias y la imposición de la administración castellana", "ok": true}, {"t": "La independencia total respecto a la Corona española", "ok": false}, {"t": "El aumento de sus privilegios forales frente a Castilla", "ok": false}, {"t": "Ningún cambio administrativo relevante", "ok": false}], "okMsg": "Correcto: los Decretos de Nueva Planta suprimieron los fueros propios e impusieron un modelo unificado castellano.", "noMsg": "Revisa la teoría: el cambio clave fue la pérdida de fueros propios y la unificación administrativa bajo el modelo castellano."}, {"type": "reflect", "kicker": "Lee el mapa del cambio", "h": "Analiza el mapa de España tras la Nueva Planta", "body": "Observa el mapa de España posterior a los Decretos de Nueva Planta trabajado en clase y localiza los territorios afectados.", "prompt": "Sobre el mapa (o describiéndolo si no lo tienes a mano), señala: 1) qué territorios (Cataluña, Aragón, Valencia) perdieron sus fueros propios, 2) qué modelo administrativo se les impuso, 3) escribe dos consecuencias que crees que pudo tener este cambio para la vida cotidiana de las personas de esos territorios."}]},
  "eso2:Abr:4": {"title": "Ilustrado y cristiano: ¿es posible hoy?", "steps": [{"type": "hook", "kicker": "Cerrando el siglo de las reformas", "h": "¿Sigue vigente hoy la pregunta que se hacían en el siglo XVIII?", "scenario": "Has visto cómo Jovellanos quería reformar España con la razón, cómo Feijoo defendía que razón y fe podían caminar juntas, y cómo Felipe V rediseñó el mapa institucional del país con los Decretos de Nueva Planta. Todo ese siglo XVIII gira, en el fondo, sobre una misma pregunta.", "body": "Esta semana cierras el mes con un texto bíblico que también advierte sobre los límites de la razón humana: <b>Colosenses 2:8</b>, y con el ensayo final que reúne todo lo aprendido sobre la Ilustración española."}, {"type": "theory", "kicker": "Una advertencia con 2000 años", "h": "Colosenses 2:8: cuidado con las \"filosofías huecas\"", "body": "El apóstol Pablo escribió: <b>«Mirad que nadie os engañe por medio de filosofías y huecas sutilezas»</b> (Col 2:8). No se trata de rechazar el pensamiento o la razón en sí (Pablo mismo razona y argumenta constantemente en sus cartas), sino de advertir contra ideas que suenan brillantes pero están vacías de verdad o alejan de lo esencial. Aplicado al siglo XVIII: la pregunta no era \"razón sí o razón no\", sino qué tipo de razón se usaba y hacia dónde conducía.", "diagram": "<b>Colosenses 2:8</b><br>\"Mirad que nadie os engañe<br>por medio de filosofías<br>y huecas sutilezas\"<br><br>No es \"razón contra fe\": es distinguir<br>razón con fundamento vs. ideas huecas"}, {"type": "quiz", "kicker": "Antes de escribir tu ensayo", "h": "¿Qué advierte realmente Colosenses 2:8?", "q": "Según el texto, ¿contra qué advierte principalmente Pablo en Colosenses 2:8?", "opts": [{"t": "Contra ideas que aparentan profundidad pero están vacías de verdad", "ok": true}, {"t": "Contra el uso de la razón en cualquier circunstancia", "ok": false}, {"t": "Contra la educación y el estudio en general", "ok": false}, {"t": "Contra los reyes que gobiernan con leyes escritas", "ok": false}], "okMsg": "Correcto: la advertencia es contra el engaño de ideas huecas, no contra pensar o razonar.", "noMsg": "Vuelve al texto: Pablo no rechaza la razón, advierte contra las \"filosofías huecas\" que engañan."}, {"type": "reflect", "kicker": "Tu ensayo final", "h": "Escribe 'Ilustración y Fe en la España del S.XVIII'", "body": "Cierra el mes escribiendo tu ensayo final de 350 a 450 palabras, integrando lo trabajado sobre Jovellanos, Feijoo, los Decretos de Nueva Planta y el debate razón-fe, con una reflexión personal apoyada en Colosenses 2:8.", "prompt": "Escribe un ensayo de 350-450 palabras titulado 'Ilustración y Fe en la España del S.XVIII' que incluya: 1) una explicación de qué buscaba la Ilustración española (Jovellanos, Feijoo) y qué cambió con la Nueva Planta, 2) tu postura argumentada sobre si razón y fe fueron aliadas o enemigas en ese siglo, con matices, 3) una reflexión final y honesta: ¿puede un cristiano ser 'ilustrado' hoy? ¿Qué significa eso en el siglo XXI, a la luz de Colosenses 2:8?"}]},
  "eso2:May:1": {"title": "Del pueblo a la metrópoli: el gran salto urbano", "steps": [{"type": "hook", "kicker": "Geografía en acción", "h": "¿Sabías que en 1900 solo 1 de cada 5 españoles vivía en una ciudad?", "scenario": "Tu bisabuela nació en un pueblo de 300 habitantes. Tú vives en una ciudad de más de 100.000. En apenas tres generaciones, España cambió por completo su forma de vivir.", "body": "Este mes investigamos <b>las ciudades españolas</b>: cómo crecieron, qué guardan en su centro histórico y qué retos enfrentan hoy. Empezamos por el principio: <b>el proceso de urbanización del siglo XX</b>."}, {"type": "theory", "kicker": "Del campo a la ciudad", "h": "La gran migración del siglo XX", "body": "Entre 1900 y 1975, millones de españoles dejaron el campo por la ciudad. Las causas: el <b>éxodo rural</b> (falta de trabajo y mecanización agrícola), la <b>industrialización</b> de zonas como Madrid, Barcelona, Bilbao o Valencia, y más tarde el <b>boom del turismo</b> en la costa. Este proceso se llama <b>urbanización</b>: el paso de una sociedad rural a otra mayoritariamente urbana.", "diagram": "1900: 20% población urbana <br> 1950: 35% población urbana <br> 1975: 70% población urbana <br> 2024: más del 80% población urbana <br> Causas: <b>éxodo rural</b> + <b>industrialización</b> + <b>turismo</b>"}, {"type": "quiz", "kicker": "Comprueba lo aprendido", "h": "¿Qué impulsó con más fuerza el crecimiento urbano español en el siglo XX?", "q": "¿Cuál fue la principal causa del crecimiento de las ciudades españolas entre 1900 y 1975?", "opts": [{"t": "El éxodo rural y la industrialización de las ciudades", "ok": true}, {"t": "La llegada masiva de turistas extranjeros a las capitales", "ok": false}, {"t": "El descubrimiento de yacimientos de petróleo en la costa", "ok": false}, {"t": "La construcción de la red de alta velocidad (AVE)", "ok": false}], "okMsg": "Correcto. El campo se vació de trabajadores y las ciudades se llenaron de fábricas y oportunidades.", "noMsg": "No exactamente. La clave fue el paso del campo a la fábrica: éxodo rural + industrialización."}, {"type": "reflect", "kicker": "Tu turno: investigación con datos", "h": "Radiografía de una ciudad en crecimiento", "body": "Vas a analizar el crecimiento urbano de una ciudad española real, con datos concretos entre 1900 y 2024. Puede ser tu ciudad, la más próxima, o una gran capital si vives en zona rural.", "prompt": "Elige una ciudad española y busca (o estima con ayuda de un adulto) su población aproximada en 1900, 1950, 1975 y 2024. Escribe un breve análisis: ¿en qué década creció más? ¿Qué causas (industria, turismo, migración) explican ese crecimiento? Mínimo 8 líneas, con al menos un dato numérico."}]},
  "eso2:May:2": {"title": "El corazón antiguo de la ciudad", "steps": [{"type": "hook", "kicker": "Explorando piedra y memoria", "h": "¿Por qué todas las ciudades españolas tienen una plaza con una iglesia enfrente?", "scenario": "Caminas por calles estrechas y torcidas, ves una catedral, una plaza mayor porticada y quizá restos de una muralla. Ese conjunto no es casualidad: es el <b>centro histórico</b>, el ADN de la ciudad.", "body": "Esta semana investigamos <b>el centro histórico</b> de las ciudades españolas: qué elementos lo forman y por qué muchos tienen un fuerte componente religioso."}, {"type": "theory", "kicker": "Anatomía del casco antiguo", "h": "Los ladrillos que cuentan la historia", "body": "El <b>centro histórico</b> (o casco antiguo) suele conservar el trazado medieval: calles estrechas, sin planificación geométrica. Sus elementos clave: la <b>catedral o iglesia mayor</b> (centro espiritual y arquitectónico), la <b>plaza mayor</b> (centro social y comercial), las <b>murallas o restos defensivos</b>, y a veces barrios como la <b>judería</b> o el <b>casco morisco</b>, que muestran la convivencia de culturas en la España medieval.", "diagram": "Centro histórico = <br> <b>Catedral / Iglesia mayor</b> (centro espiritual) <br> <b>Plaza Mayor</b> (centro social) <br> <b>Murallas</b> (defensa) <br> <b>Callejero medieval</b> (trazado irregular)"}, {"type": "quiz", "kicker": "Comprueba lo aprendido", "h": "¿Qué elemento es típico de un centro histórico español?", "q": "¿Cuál de estos elementos forma parte habitual del centro histórico de una ciudad española?", "opts": [{"t": "Una catedral o iglesia mayor junto a la plaza principal", "ok": true}, {"t": "Un centro comercial de última generación", "ok": false}, {"t": "Una terminal de aeropuerto internacional", "ok": false}, {"t": "Un polígono industrial de nueva construcción", "ok": false}], "okMsg": "Correcto. La iglesia o catedral suele ser el corazón simbólico del casco histórico.", "noMsg": "No es eso. Piensa en lo que sobrevive desde la Edad Media: templos, plazas y murallas."}, {"type": "reflect", "kicker": "Tu turno: trabajo de campo", "h": "El mapa histórico de tu ciudad", "body": "Investiga el centro histórico de tu ciudad, o el de la ciudad más próxima si vives en un pueblo o zona rural.", "prompt": "Haz una lista de al menos 5 elementos históricos y/o religiosos del centro histórico investigado (iglesia, plaza, muralla, convento, casco antiguo, etc.). Para cada uno, escribe una frase sobre su origen o función original. Si puedes, adjunta o describe una foto."}]},
  "eso2:May:3": {"title": "¿Turistas o vecinos? La ciudad en disputa", "steps": [{"type": "hook", "kicker": "Un dilema real", "h": "El piso de tu vecina ahora es un apartamento turístico. Ella tuvo que mudarse a las afueras.", "scenario": "En el centro histórico que investigaste la semana pasada, cada vez hay más pisos turísticos y menos vecinos de toda la vida. El turismo trae dinero... pero también cambia la ciudad para siempre.", "body": "Esta semana debatimos uno de los grandes <b>retos urbanos</b> actuales: <b>sostenibilidad, despoblación y turismo masivo</b>."}, {"type": "theory", "kicker": "Los retos de la ciudad del siglo XXI", "h": "Cuando demasiados visitantes cambian una ciudad", "body": "El <b>turismo masivo</b> genera empleo e ingresos, pero también <b>gentrificación</b>: los precios de la vivienda suben tanto que los vecinos originales ya no pueden pagarlos y se van. Además, mientras las ciudades turísticas se saturan, muchos pueblos del interior sufren <b>despoblación</b>. El reto es lograr <b>sostenibilidad</b>: que la ciudad crezca sin perder su identidad ni expulsar a quienes la habitan.", "diagram": "Turismo masivo: <br> + <b>Beneficio económico</b> <br> – <b>Gentrificación</b> (suben precios, vecinos se van) <br> – <b>Pérdida de identidad cultural</b> <br> – <b>Saturación de servicios</b>"}, {"type": "quiz", "kicker": "Comprueba lo aprendido", "h": "¿Qué es la gentrificación?", "q": "¿Cómo se define la 'gentrificación' en el contexto de una ciudad turística?", "opts": [{"t": "El proceso por el que suben los precios de un barrio y los vecinos originales deben marcharse", "ok": true}, {"t": "La construcción de nuevas murallas defensivas", "ok": false}, {"t": "El aumento de la población rural", "ok": false}, {"t": "La prohibición total de recibir turistas", "ok": false}], "okMsg": "Correcto. Es un cambio de barrio que expulsa, a menudo sin querer, a quienes siempre vivieron allí.", "noMsg": "No es eso. Piensa en lo que le pasó a la vecina del ejemplo: subida de precios y desplazamiento."}, {"type": "reflect", "kicker": "Tu turno: debate con argumentos", "h": "¿Puede el turismo masivo destruir la identidad de una ciudad?", "body": "Vas a preparar un debate real, con argumentos a favor y en contra, sobre el impacto del turismo masivo en las ciudades españolas.", "prompt": "Escribe dos argumentos a favor del turismo masivo (beneficios) y dos en contra (riesgos para la identidad cultural). Después, da tu opinión personal razonada: ¿qué medidas propondrías tú para que el turismo no destruya la identidad de una ciudad? Mínimo 8 líneas."}]},
  "eso2:May:4": {"title": "Dominar la tierra: cuidar, no destruir", "steps": [{"type": "hook", "kicker": "La Biblia y la ciudad", "h": "¿Qué significa realmente 'tener dominio' sobre la tierra?", "scenario": "Hemos visto ciudades que crecen sin control, centros históricos amenazados y turismo que expulsa a los vecinos. ¿Tiene la Biblia algo que decir sobre cómo debemos tratar los lugares donde vivimos?", "body": "Cerramos el mes con <b>Génesis 1:28</b>, donde Dios da a la humanidad 'dominio' sobre la tierra. Pero ese dominio no es un permiso para destruir: es una llamada a la <b>administración responsable</b>."}, {"type": "theory", "kicker": "Dominio no es destrucción", "h": "Génesis 1:28: administrar, no arrasar", "body": "\"Y los bendijo Dios: fructificad y multiplicaos, y llenad la tierra\" (Gen 1:28). El término bíblico 'dominio' se entiende, en su contexto original, como el de un <b>mayordomo</b> o administrador que cuida lo que se le confía, no como el de un dueño que explota sin límites. Aplicado a nuestras ciudades: cuidar el centro histórico, frenar la despoblación y gestionar el turismo con responsabilidad es una forma concreta de ejercer ese 'dominio' bíblico sobre el lugar donde vivimos.", "diagram": "<b>Génesis 1:28</b>: 'llenad la tierra' <br> Dominio = <b>administración responsable</b>, no explotación <br> Ciudad cuidada = fruto de un buen 'mayordomo'"}, {"type": "quiz", "kicker": "Comprueba lo aprendido", "h": "¿Qué significa 'dominio' en Génesis 1:28?", "q": "Según el sentido bíblico de Génesis 1:28, ¿qué implica tener 'dominio' sobre la tierra?", "opts": [{"t": "Administrar y cuidar responsablemente lo que Dios ha creado", "ok": true}, {"t": "Explotar los recursos sin ningún límite", "ok": false}, {"t": "Evitar por completo construir ciudades", "ok": false}, {"t": "Un permiso exclusivo para gobernantes", "ok": false}], "okMsg": "Correcto. Dominio bíblico es mayordomía: cuidar y administrar, no destruir.", "noMsg": "No es eso. El 'dominio' bíblico se parece más al de un cuidador responsable que al de un explotador."}, {"type": "reflect", "kicker": "Tu turno: entregable final del mes", "h": "¿Cómo cuidamos nuestras ciudades?", "body": "Es momento de reunir todo lo trabajado este mes (crecimiento urbano, centro histórico, retos del turismo) en tu informe final, iluminado por la idea bíblica de administración responsable.", "prompt": "Elabora el informe 'La ciudad española: historia y retos'. Incluye: 1) un dato sobre el crecimiento urbano de tu ciudad o la más próxima, 2) dos elementos de su centro histórico, 3) un reto urbano actual (turismo, despoblación o sostenibilidad), y 4) una conclusión personal que conecte con Génesis 1:28: ¿qué significaría para ti ejercer un 'dominio responsable' sobre tu propia ciudad?"}]},
  "eso2:Jun:1": {"title": "Fuenteovejuna: el pueblo unido contra la injusticia", "steps": [{"type": "hook", "kicker": "Teatro con las manos en la masa", "h": "¿Puede un pueblo entero rebelarse contra un tirano y quedar impune?", "scenario": "En un pequeño pueblo llamado Fuente Ovejuna, un comendador abusa de su poder sobre los vecinos. Hartos de humillaciones, todos deciden actuar juntos... y cuando el juez pregunta quién es culpable, todo el pueblo responde lo mismo: <i>\"Fuenteovejuna lo hizo\"</i>.", "body": "Este mes entramos en el <b>Teatro del Siglo de Oro</b>, con Lope de Vega y Calderón de la Barca. Empezamos con el <b>Acto I de Fuente Ovejuna</b>, una obra sobre la dignidad humana y la justicia."}, {"type": "theory", "kicker": "El teatro como fenómeno popular", "h": "Los corrales de comedias y Lope de Vega", "body": "En el Siglo de Oro, el teatro se representaba en los <b>corrales de comedias</b>: patios interiores de casas convertidos en escenarios al aire libre, donde asistía todo tipo de público, desde nobles a artesanos. <b>Lope de Vega</b>, el autor más prolífico de la época, escribió <b>Fuente Ovejuna</b>, basada en un hecho histórico: un pueblo que se levanta contra el abuso de poder de su señor feudal, defendiendo la <b>dignidad humana</b> por encima del miedo.", "diagram": "Corral de comedias = teatro popular al aire libre <br> <b>Lope de Vega</b> → escribe <b>Fuente Ovejuna</b> <br> Tema central: <b>dignidad humana</b> frente al abuso de poder"}, {"type": "quiz", "kicker": "Comprueba lo aprendido", "h": "¿Qué era un corral de comedias?", "q": "¿Qué era un 'corral de comedias' en el Siglo de Oro español?", "opts": [{"t": "Un patio interior convertido en escenario de teatro popular al aire libre", "ok": true}, {"t": "Un edificio exclusivo solo para la nobleza", "ok": false}, {"t": "Una escuela de actores profesionales", "ok": false}, {"t": "Un templo dedicado a representaciones religiosas privadas", "ok": false}], "okMsg": "Correcto. Era teatro popular, abierto a todo tipo de público, en un patio al aire libre.", "noMsg": "No es eso. Piensa en un patio de vecinos convertido en escenario abierto a todo el pueblo."}, {"type": "reflect", "kicker": "Tu turno: lectura y análisis", "h": "El mensaje de Fuente Ovejuna sobre la justicia", "body": "Lee (o repasa) el Acto I de Fuente Ovejuna, en su versión adaptada para 2º de ESO.", "prompt": "Escribe un análisis breve: ¿qué injusticia sufre el pueblo en el Acto I? ¿Por qué crees que Lope de Vega decide que sea 'todo el pueblo' quien actúe, en lugar de un solo héroe individual? Relaciona tu respuesta con la idea de dignidad humana. Mínimo 8 líneas."}]},
  "eso2:Jun:2": {"title": "Segismundo: ¿preso de su destino o dueño de su libertad?", "steps": [{"type": "hook", "kicker": "Encerrado desde su nacimiento", "h": "¿Y si te dijeran que naciste destinado a hacer el mal, sin poder elegir otra cosa?", "scenario": "Segismundo ha vivido encerrado en una torre desde bebé porque una profecía anunciaba que sería un príncipe cruel. Cuando por fin sale y descubre el mundo, tiene que decidir: ¿cumplir la profecía o forjar su propio camino?", "body": "Esta semana analizamos <b>La vida es sueño</b>, de Calderón de la Barca, y su gran pregunta filosófica: <b>¿tiene Segismundo libre albedrío?</b>"}, {"type": "theory", "kicker": "Destino frente a libre albedrío", "h": "Calderón y la gran pregunta barroca", "body": "<b>Calderón de la Barca</b> plantea en <b>La vida es sueño</b> el conflicto entre el destino (lo que parece inevitable) y el <b>libre albedrío</b> (la capacidad de elegir). Segismundo, al enfrentarse a su profecía, descubre que puede actuar con nobleza aunque las circunstancias le empujen hacia el mal. La Biblia, por su parte, también enseña que Dios nos da <b>libertad para elegir</b>: el ser humano no está condenado a actuar mal por su origen o sus circunstancias, sino que puede optar por el bien.", "diagram": "<b>Segismundo</b> encerrado desde niño <br> ¿Destino fijo? → o <b>libre albedrío</b>: elige actuar con nobleza <br> Fe cristiana: Dios da libertad real para elegir el bien"}, {"type": "quiz", "kicker": "Comprueba lo aprendido", "h": "¿Qué es el libre albedrío?", "q": "En el contexto de La vida es sueño, ¿qué significa 'libre albedrío'?", "opts": [{"t": "La capacidad de la persona de elegir sus propias acciones, más allá del destino o las circunstancias", "ok": true}, {"t": "La obligación de cumplir siempre una profecía", "ok": false}, {"t": "Un tipo de vestuario usado en el teatro barroco", "ok": false}, {"t": "El nombre del palacio donde vive Segismundo", "ok": false}], "okMsg": "Correcto. Es la capacidad de elegir, aunque el destino parezca marcado.", "noMsg": "No es eso. Piensa en la decisión de Segismundo de actuar bien pese a la profecía."}, {"type": "reflect", "kicker": "Tu turno: análisis filosófico", "h": "¿Elige Segismundo su destino?", "body": "Vas a analizar si Segismundo tiene realmente libre albedrío, y qué dice la Biblia sobre la libertad humana de elegir.", "prompt": "Responde: ¿crees que Segismundo tiene libre albedrío o está condenado por la profecía? Da un ejemplo concreto de la obra. Después, busca o recuerda una idea bíblica sobre la libertad de elegir el bien o el mal, y compárala con la situación de Segismundo. Mínimo 8 líneas."}]},
  "eso2:Jun:3": {"title": "Llamados a la libertad: fe y teatro", "steps": [{"type": "hook", "kicker": "Cadenas que se rompen", "h": "¿Qué tienen en común una torre en Polonia y una carta escrita en el siglo I?", "scenario": "Segismundo pasa de estar encadenado en una torre a ser libre para decidir su propio destino. Siglos antes, el apóstol Pablo escribió a los Gálatas sobre otro tipo de libertad: la que Cristo ofrece.", "body": "Esta semana conectamos el drama de Calderón con <b>Gálatas 5:1</b>: \"Para libertad fue Cristo quien nos libertó; manteneos firmes en la libertad.\""}, {"type": "theory", "kicker": "Libertad con propósito", "h": "Gálatas 5:1 y La vida es sueño", "body": "Gálatas 5:1 enseña que la <b>libertad</b> que ofrece la fe cristiana no es un fin en sí mismo, sino un llamado a <b>mantenerse firme</b>, usando esa libertad con responsabilidad y propósito, no para el libertinaje. Es exactamente lo que aprende Segismundo: su gran lección no es 'hacer lo que quiera' sin límites, sino usar su libertad para <b>actuar con nobleza y justicia</b>, incluso cuando nadie se lo exige.", "diagram": "<b>Gálatas 5:1</b>: 'Para libertad fuisteis llamados' <br> Libertad ≠ hacer cualquier cosa (libertinaje) <br> Libertad = <b>responsabilidad</b> + propósito <br> Segismundo: usa su libertad para el bien"}, {"type": "quiz", "kicker": "Comprueba lo aprendido", "h": "¿Qué tipo de libertad describe Gálatas 5:1?", "q": "Según Gálatas 5:1, ¿cómo debe entenderse la libertad que da la fe cristiana?", "opts": [{"t": "Como una libertad responsable, que se mantiene firme y no se usa para el libertinaje", "ok": true}, {"t": "Como el derecho a hacer cualquier cosa sin ninguna consecuencia", "ok": false}, {"t": "Como la obligación de vivir encerrado, igual que Segismundo al inicio", "ok": false}, {"t": "Como un concepto exclusivo del teatro barroco, sin relación con la fe", "ok": false}], "okMsg": "Correcto. Es una libertad con propósito: firme, responsable, orientada al bien.", "noMsg": "No es eso. Gálatas 5:1 habla de una libertad que se sostiene con responsabilidad, no de hacer cualquier cosa."}, {"type": "reflect", "kicker": "Tu turno: conexión bíblica", "h": "De la torre de Segismundo a la libertad en Cristo", "body": "Vas a conectar de forma personal el drama de Calderón con el versículo de Gálatas 5:1.", "prompt": "Escribe un texto breve explicando cómo el cambio de Segismundo (de prisionero a hombre libre y responsable) puede entenderse como una ilustración de Gálatas 5:1. ¿En qué momento de tu propia vida sientes que puedes 'mantenerte firme' usando bien tu libertad? Mínimo 8 líneas."}]},
  "eso2:Jun:4": {"title": "El Siglo de Oro en escena: tu turno de escribir", "steps": [{"type": "hook", "kicker": "De espectador a dramaturgo", "h": "¿Y si esta semana fueras tú quien escribe para el corral de comedias?", "scenario": "Has leído a Lope de Vega y a Calderón, has debatido sobre justicia y libertad. Ahora te toca coger la pluma: vas a escribir tu propia escena dramática, inspirada en Fuente Ovejuna o en La vida es sueño.", "body": "Cerramos el mes con el gran <b>Proyecto teatral 'El Siglo de Oro en escena'</b>: tu propia creación literaria."}, {"type": "theory", "kicker": "Cómo se construye una escena dramática", "h": "Los ingredientes del teatro del Siglo de Oro", "body": "Una buena escena teatral necesita: <b>personajes</b> con una motivación clara, un <b>conflicto</b> (una injusticia, una decisión difícil, un dilema moral), un <b>lugar y tiempo</b> definidos, y diálogos que avancen la acción. Tanto Lope de Vega como Calderón usaban el conflicto moral —la justicia frente al abuso, la libertad frente al destino— como motor de sus obras. Tu escena puede recoger ese mismo espíritu: un personaje que, como Segismundo, decide usar su libertad para actuar bien, o como el pueblo de Fuenteovejuna, se une frente a una injusticia.", "diagram": "Escena dramática = <br> <b>Personajes</b> + <b>Conflicto</b> (justicia o libertad) + <b>Lugar/tiempo</b> + <b>Diálogo</b> <br> Inspiración: Fuente Ovejuna o La vida es sueño"}, {"type": "quiz", "kicker": "Comprueba lo aprendido", "h": "¿Qué elemento no puede faltar en una escena dramática?", "q": "¿Cuál de estos elementos es imprescindible para construir una buena escena dramática del Siglo de Oro?", "opts": [{"t": "Un conflicto claro, como una injusticia o un dilema moral", "ok": true}, {"t": "Efectos especiales por ordenador", "ok": false}, {"t": "Que la escena se desarrolle exclusivamente en el siglo XXI", "ok": false}, {"t": "Que no aparezca ningún personaje que hable", "ok": false}], "okMsg": "Correcto. El conflicto —moral, social o de libertad— es el motor de toda buena escena teatral.", "noMsg": "No es eso. Piensa en lo que mueve a Fuenteovejuna o a Segismundo: un conflicto de fondo."}, {"type": "reflect", "kicker": "Tu turno: entregable final del mes", "h": "Escribe tu propia escena del Siglo de Oro", "body": "Es el momento de crear tu proyecto teatral final, inspirado en la dignidad humana de Fuente Ovejuna o en la libertad de La vida es sueño.", "prompt": "Escribe una escena dramática de una página, con al menos dos personajes y un conflicto claro (una injusticia que enfrentar, o una decisión sobre usar bien la libertad). Puedes inspirarte en el espíritu de Gálatas 5:1 ('Para libertad fuisteis llamados'): que tu personaje principal tome una decisión libre y responsable en un momento difícil. Incluye acotaciones breves entre paréntesis."}]},
  "eso2:Jul:1": {"title": "Ensayo de síntesis: grandeza, crisis y fe", "steps": [{"type": "hook", "kicker": "Proyecto Final · Semana 1", "h": "¿Cómo se cuenta la historia de todo un imperio en 500 palabras?", "scenario": "Es julio. Detrás de ti quedan diez meses de curso: el Imperio Español del siglo XVI, Don Quijote cabalgando por La Mancha, villancicos del Siglo de Oro, la crisis y el Barroco del siglo XVII, los versos de Quevedo y Góngora, la Ilustración de los Borbones, las ciudades y catedrales españolas, y el teatro de Lope y Calderón.", "body": "Hoy empieza tu <b>proyecto final</b>: un ensayo de síntesis que une tres siglos de historia de España en un solo hilo narrativo. No se trata de listar fechas, sino de responder a una pregunta más profunda: ¿qué hace que un pueblo mantenga su <b>identidad</b> a través de la grandeza, la crisis y la fe?"}, {"type": "theory", "kicker": "Cómo se construye un ensayo de síntesis", "h": "Tres siglos, tres movimientos, un mismo hilo", "body": "Un buen ensayo de síntesis no resume todo lo que sabes: <b>selecciona</b> lo esencial y lo conecta con una idea central. Para 'La España de los siglos XVI-XVIII: grandeza, crisis y fe' puedes organizar tus 400-500 palabras en tres movimientos que ya conoces bien: la <b>grandeza</b> del Imperio del siglo XVI (expansión, Don Quijote, la fe que sostenía la Navidad del Siglo de Oro), la <b>crisis</b> del siglo XVII (decadencia, el desengaño barroco de Quevedo y Góngora, el teatro de Lope y Calderón como espejo de una sociedad en tensión), y la <b>reforma</b> del siglo XVIII (la Ilustración, las reformas borbónicas, la razón buscando nuevos caminos). Cada movimiento necesita un dato histórico concreto, no solo una idea general.", "diagram": "<b>GRANDEZA</b> (S.XVI): Imperio + fe + letras <br> <b>CRISIS</b> (S.XVII): decadencia + Barroco + desengaño <br> <b>REFORMA</b> (S.XVIII): Ilustración + razón + cambio <br> → un hilo conductor: <b>identidad española</b>"}, {"type": "quiz", "kicker": "Comprueba antes de escribir", "h": "¿Qué distingue a un ensayo de síntesis de un simple resumen?", "q": "¿Cuál es la diferencia clave entre un ensayo de síntesis y un resumen de apuntes?", "opts": [{"t": "El ensayo conecta los datos alrededor de una idea central; el resumen solo los enumera", "ok": true}, {"t": "El ensayo no necesita datos históricos concretos", "ok": false}, {"t": "El resumen debe ser más largo que el ensayo", "ok": false}, {"t": "No hay ninguna diferencia real entre ambos", "ok": false}], "okMsg": "Exacto. Sintetizar es elegir y conectar, no acumular.", "noMsg": "Repasa la teoría: la clave está en tejer los datos alrededor de una idea, no en enumerarlos."}, {"type": "reflect", "kicker": "Tu tarea de esta semana", "h": "Escribe el primer borrador de tu ensayo", "body": "Redacta un ensayo de 400-500 palabras titulado <b>'La España de los siglos XVI-XVIII: grandeza, crisis y fe'</b>. Debe incluir al menos un dato o ejemplo concreto de cada siglo (XVI, XVII y XVIII) que hayas estudiado este curso, y cerrar con una reflexión personal sobre qué papel jugó la fe en esa identidad histórica.", "prompt": "Escribe tu ensayo de síntesis (400-500 palabras). Estructura sugerida: párrafo 1 - grandeza del Imperio (S.XVI); párrafo 2 - crisis y Barroco (S.XVII); párrafo 3 - Ilustración y reforma (S.XVIII); párrafo final - tu reflexión sobre la fe como hilo conductor de la identidad española."}]},
  "eso2:Jul:2": {"title": "Un mapa mental para todo el año", "steps": [{"type": "hook", "kicker": "Proyecto Final · Semana 2", "h": "¿Puedes dibujar un curso entero en una sola página?", "scenario": "Tienes tu ensayo escrito de la semana pasada. Ahora toca un reto distinto: en lugar de escribir con frases, vas a pensar con <b>líneas y conexiones</b>. Historia, geografía y literatura no son islas separadas: se entrelazan constantemente.", "body": "Un <b>mapa mental</b> te obliga a ver el bosque completo, no solo los árboles sueltos. Hoy vas a construir el mapa que resume tu año de 2º de ESO."}, {"type": "theory", "kicker": "Historia, geografía y literatura conectadas", "h": "Cómo diseñar un mapa mental de síntesis", "body": "Coloca en el centro la idea principal: <b>'España, siglos XVI-XVIII'</b>. De ahí salen tres grandes ramas: <b>Historia</b> (Imperio, decadencia, Ilustración, reformas borbónicas), <b>Geografía</b> (las ciudades españolas que estudiaste y su papel en cada época) y <b>Literatura</b> (Don Quijote, la poesía barroca de Quevedo y Góngora, el teatro de Lope y Calderón). La clave de un buen mapa mental no es solo dividir en ramas, sino trazar <b>conexiones cruzadas</b> entre ellas: por ejemplo, cómo la crisis del siglo XVII (historia) se refleja en el desengaño barroco (literatura) y en el declive de ciertas ciudades (geografía).", "diagram": "<b>CENTRO</b>: España S.XVI-XVIII <br> <b>Rama 1</b>: Historia (Imperio → crisis → Ilustración) <br> <b>Rama 2</b>: Geografía (ciudades y su papel) <br> <b>Rama 3</b>: Literatura (Quijote, Barroco, teatro) <br> + <b>líneas cruzadas</b> entre ramas"}, {"type": "quiz", "kicker": "Antes de dibujar", "h": "¿Qué hace fuerte a un mapa mental?", "q": "¿Cuál es el elemento que más enriquece un mapa mental de síntesis?", "opts": [{"t": "Las conexiones cruzadas entre ramas distintas (por ejemplo, historia con literatura)", "ok": true}, {"t": "Usar solo una rama con muchísimo texto", "ok": false}, {"t": "Evitar cualquier relación entre geografía e historia", "ok": false}, {"t": "Copiar el índice del libro de texto sin cambios", "ok": false}], "okMsg": "Correcto. Las conexiones cruzadas son las que muestran comprensión real.", "noMsg": "Piénsalo de nuevo: lo valioso de un mapa mental está en cómo se relacionan las ramas entre sí."}, {"type": "reflect", "kicker": "Tu tarea de esta semana", "h": "Construye tu mapa mental del año", "body": "Diseña un mapa mental (en papel, cartulina o digital) con el centro 'España, siglos XVI-XVIII' y al menos tres ramas: Historia, Geografía y Literatura. Añade en cada rama 3-4 elementos concretos del curso y traza al menos dos conexiones cruzadas entre ramas distintas.", "prompt": "Describe por escrito tu mapa mental: qué va en el centro, qué contiene cada una de las tres ramas (Historia, Geografía, Literatura) y explica dos conexiones cruzadas que hayas trazado entre ellas."}]},
  "eso2:Jul:3": {"title": "Ocho minutos para contar un año", "steps": [{"type": "hook", "kicker": "Proyecto Final · Semana 3", "h": "¿Qué dirías si solo tuvieras 8 minutos para presentar todo un curso?", "scenario": "Tu ensayo está escrito, tu mapa mental está trazado. Ahora es el momento de la voz: una <b>presentación oral</b> de 8 minutos ante tu grupo o tu familia.", "body": "Hablar en público sobre lo que has aprendido no es solo repetir datos: es demostrar que entiendes la <b>argumentación</b>, que sabes defender una idea con ejemplos y cerrarla con una reflexión propia."}, {"type": "theory", "kicker": "Argumentación oral nivel ESO 2", "h": "La estructura de tu presentación de 8 minutos", "body": "Una presentación oral sólida en 2º ESO necesita: <b>3 eventos históricos</b> (elige entre el auge del Imperio, la crisis del XVII o las reformas borbónicas del XVIII), <b>1 obra literaria</b> (Don Quijote, un poema barroco de Quevedo o Góngora, o una obra de teatro de Lope o Calderón) y <b>1 reflexión personal</b> que cierre tu exposición. El secreto de una buena argumentación oral es el <b>orden</b>: presenta primero los hechos, después la obra literaria que los refleja, y termina con tu propia interpretación. Cuida también el tiempo: 8 minutos exigen practicar antes, no improvisar.", "diagram": "<b>Apertura</b>: presenta el tema <br> <b>3 eventos históricos</b>: Imperio / crisis / Ilustración <br> <b>1 obra literaria</b>: Quijote / poesía barroca / teatro <br> <b>1 reflexión final</b>: tu interpretación personal"}, {"type": "quiz", "kicker": "Antes de presentar", "h": "¿Qué elementos son obligatorios en tu presentación?", "q": "¿Qué debe incluir obligatoriamente tu presentación oral de 8 minutos?", "opts": [{"t": "3 eventos históricos, 1 obra literaria y 1 reflexión personal", "ok": true}, {"t": "Solo datos de geografía, sin literatura ni historia", "ok": false}, {"t": "Únicamente una lista de fechas sin comentario", "ok": false}, {"t": "5 obras literarias distintas y ningún evento histórico", "ok": false}], "okMsg": "Así es. Esa combinación es la que exige la argumentación de nivel ESO 2.", "noMsg": "Revisa la estructura: necesitas 3 eventos históricos + 1 obra literaria + 1 reflexión."}, {"type": "reflect", "kicker": "Tu tarea de esta semana", "h": "Prepara y ensaya tu presentación oral", "body": "Elabora el guion de tu presentación de 8 minutos: elige 3 eventos históricos, 1 obra literaria y redacta tu reflexión final. Practica en voz alta al menos dos veces antes de presentarla.", "prompt": "Escribe el guion completo de tu presentación oral (8 minutos): enumera los 3 eventos históricos elegidos, la obra literaria que has seleccionado y redacta el párrafo de reflexión final con el que la cerrarás."}]},
  "eso2:Jul:4": {"title": "Dios es nuestro amparo: clausura del curso", "steps": [{"type": "hook", "kicker": "Proyecto Final · Semana 4", "h": "¿Qué queda cuando termina un año entero de aprender?", "scenario": "Has escrito tu ensayo, dibujado tu mapa mental y presentado en voz alta la historia de España entre grandeza, crisis y fe. Ahora, en esta última sesión del curso, toca detenerse y mirar hacia adentro.", "body": "El Salmo 46:1 dice: <b>'Dios es nuestro amparo.'</b> A lo largo de tres siglos, España vivió momentos de esplendor y momentos de derrumbe, y en ambos, la fe fue el amparo que sostuvo a generaciones enteras. Hoy cierras tu curso con esa misma verdad."}, {"type": "theory", "kicker": "Un curso que termina, una transformación que continúa", "h": "No os conforméis a este siglo", "body": "Romanos 12:2 dice: <b>'No os conforméis a este siglo, sino transformaos por medio de la renovación de vuestro entendimiento.'</b> Has pasado un año estudiando cómo España se transformó una y otra vez: del Imperio a la crisis, de la crisis a la Ilustración. Esa misma capacidad de renovación es la que Pablo pide para tu propia vida. El Salmo 46:1 y Romanos 12:2 se unen en una sola idea: <b>Dios es el amparo</b> que sostiene incluso en tiempos de cambio, y tu mente puede <b>renovarse</b> constantemente, igual que lo hizo un pueblo entero a lo largo de tres siglos.", "diagram": "<b>Salmo 46:1</b>: 'Dios es nuestro amparo' <br> <b>Romanos 12:2</b>: 'Transformaos por la renovación' <br> Un año de historia + fe = <b>una identidad que se renueva sin perder su amparo</b>"}, {"type": "quiz", "kicker": "Cierre del curso", "h": "¿Cuál es el versículo de clausura de todo el año?", "q": "¿Qué versículo se usa para cerrar espiritualmente el curso académico completo?", "opts": [{"t": "Romanos 12:2: 'No os conforméis a este siglo, sino transformaos por medio de la renovación'", "ok": true}, {"t": "Génesis 1:1", "ok": false}, {"t": "Un versículo inventado para la ocasión", "ok": false}, {"t": "Ningún versículo, el curso cierra solo con datos históricos", "ok": false}], "okMsg": "Correcto. Romanos 12:2 es el versículo de referencia oficial de esta clausura.", "noMsg": "El versículo de cierre del curso es Romanos 12:2, aunque la sesión también recuerda el Salmo 46:1."}, {"type": "reflect", "kicker": "Tu reflexión final del curso", "h": "Cierra tu año con gratitud y renovación", "body": "Escribe una reflexión final personal sobre tu año de 2º de ESO: qué aprendiste sobre España, sobre ti mismo y sobre tu fe. Conecta tu reflexión con el Salmo 46:1 ('Dios es nuestro amparo') y con Romanos 12:2 ('transformaos por medio de la renovación').", "prompt": "Escribe tu reflexión final de cierre de curso: menciona un aprendizaje histórico que te haya marcado, cómo has cambiado tú a lo largo del año, y explica con tus propias palabras qué significa para ti que 'Dios es nuestro amparo' mientras te 'transformas por medio de la renovación de tu entendimiento'."}]},
});
